/* Static content data for Waqt24 (Du'a, Hadees, Ilm names/words/myths, quiz bank). Loaded before the main script in index.html. */
const DUAS = [
  {cat:'Roz Marra', title:'Sone ki Dua', arabic:'اَللّٰھُمَّ بِاسْمِکَ أَمُوتُ وَأَحْیَا', translit:"Allahumma bismika amutu wa ahya.", meaning:'Aye Allah! Main Tere hi naam par marta (sota) hoon aur zinda hota (jagta) hoon.', ref:'Sahih Bukhari', ent:"Dua Before Sleeping", enm:"In Your name, O Allah, I die and I live."},
  {cat:'Roz Marra', title:'Jagne ki Dua', arabic:'الْحَمْدُ لِلَّهِ الَّذِی أَحْیَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَیْهِ النُّشُورُ', translit:'Alhamdu lillahil-lazi ahyana ba\'da ma amatana wa ilaihin-nushur', meaning:'Sab tareef Allah ke liye hai jisne humein maut ke baad zinda kiya, aur usi ki taraf lautna hai.', ref:'Sahih Bukhari', ent:"Dua on Waking Up", enm:"All praise is for Allah, who gave us life after causing us to die, and to Him is the resurrection."},
  {cat:'Khana', title:'Khana Shuru Karne ki Dua', arabic:'بِسْمِ اللَّهِ وَعَلَیٰ بَرَکَةِ اللَّهِ', translit:'Bismillahi wa ala barakatillah.', meaning:'Allah ke naam se aur Allah ki barkat par (main khana shuru karta hoon).', ref:'Sahih Bukhari', ent:"Dua Before Eating", enm:"In the name of Allah, and with the blessings of Allah, I begin my meal."},
  {cat:'Khana', title:'Khane ka hisaab se bachne ki dua', arabic:'الْحَمْدُ لِلَّهِ الَّذِی أَطْعَمَنِی هَذَا وَرَزَقَنِیهِ مِنْ غَیْرِ حَوْلٍ مِنِّی وَلَا قُوَّةٍ', translit:'Alhamdulillahillazi at\'amani haza wa razaqnihi min ghairi haulin minni wa la quwwatin.', meaning:'Tamam taarifain us Allah ke liye hain jisne mujhe yeh khana khilaya aur meri taqat ya qudrat na hone ke bawajood mujhe yeh ata farmaya.', ref:'Abu Dawood, Tirmidhi, Ibn Majah', info:'Hadees: Hazrat Mu\'adh bin Anas (RA) se riwayat hai ki Nabi ﷺ ne farmaya: jo shakhs khana khaye aur phir yeh dua padhe, uske pichle aur aainda ke gunah bakhsh diye jayenge. Yeh dua khane ki niamat par shukr ka izhaar hai, aur iss baat ka iqrar ki rizq Allah ki taraf se hai, apni taqat ya qudrat se nahi.', ent:"Dua After Eating", enm:"All praise is for Allah, who fed me this food and provided it to me without any might or power from me.", eninfo:"Hadith: Mu'adh bin Anas (RA) narrated that the Prophet ﷺ said: whoever eats food and then says this dua, his past and future sins will be forgiven. It is an expression of gratitude for the blessing of food, and an acknowledgement that provision comes from Allah, not from one's own strength."},
  {cat:'Safar', title:'Safar ki Dua', arabic:'سُبْحَانَ الَّذِی سَخَّرَ لَنَا هَذَا وَمَا کُنَّا لَهُ مُقْرِنِینَ', translit:'Subhanal-lazi sakhkhara lana haza wa ma kunna lahu muqrinin', meaning:'Pak hai woh Zaat jisne is sawari ko humare kaabu mein diya.', ref:'Sahih Muslim', ent:"Travel Dua", enm:"Glory be to the One who subjected this to us; we could never have controlled it by ourselves."},
  {cat:'Masjid', title:'Masjid Mein Dakhil Hone ki Dua', arabic:'اللَّهُمَّ افْتَحْ لِی أَبْوَابَ رَحْمَتِکَ', translit:'Allahummaf-tah li abwaba rahmatik', meaning:'Ae Allah, mere liye apni rehmat ke darwaze khol de.', ref:'Sahih Muslim', ent:"Dua Entering the Masjid", enm:"O Allah, open for me the doors of Your mercy."},
  {cat:'Masjid', title:'Masjid Se Nikalne ki Dua', arabic:'اللَّهُمَّ إِنِّی أَسْأَلُکَ مِنْ فَضْلِکَ', translit:'Allahumma inni as\'aluka min fadlik', meaning:'Ae Allah, main aapse aapke fazl ka sawal karta hoon.', ref:'Sahih Muslim', ent:"Dua Leaving the Masjid", enm:"O Allah, I ask You for Your bounty."},
  {cat:'Pareshani', title:'Pareshani Ke Waqt ki Dua', arabic:'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَکِیلُ', translit:"Hasbunallahu wa ni'mal wakil", meaning:'Allah humare liye kaafi hai aur woh behtareen kaarsaaz hai.', ref:'Qur’an 3:173', ent:"Dua in Hardship", enm:"Allah is sufficient for us, and He is the best disposer of affairs."},
  {cat:'Ghar', title:'Ghar Mein Dakhil Hone ki Dua', arabic:'بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَی رَبِّنَا تَوَکَّلْنَا', translit:"Bismillahi walajna wa bismillahi kharajna wa 'ala rabbina tawakkalna", meaning:'Allah ke naam se hum andar aaye aur Allah ke naam se nikle, aur apne Rab par bharosa kiya.', ref:'Abu Dawood', ent:"Dua Entering the Home", enm:"In the name of Allah we entered, and in the name of Allah we left, and upon our Lord we rely."},
  {cat:'Ramzan', title:'Iftar karne ki dua', arabic:'ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ', translit:"Zahabaz-zama'u wabtallatil-'uruqu wa thabatal-ajru in sha Allah", meaning:'Pyaas chali gayi, rag-tarein tar ho gayi, aur agar Allah ne chaha to ajar sabit ho gaya.', ref:'Abu Dawood', ent:"Dua for Breaking the Fast", enm:"The thirst has gone, the veins are moistened, and the reward is confirmed, if Allah wills."},
  {cat:'Rabbana', title:"Qabooliyat Ki Dua", arabic:"رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّکَ أَنتَ ٱلسَّمِیعُ ٱلۡعَلِیمُ", translit:"Rabbana taqabbal minna innaka antas Sami'ul 'Aleem", meaning:"Ae hamare Rab, hamari taraf se (yeh amal) qabool farma. Beshak Tu hi sunne wala aur jaanne wala hai.", ref:"Qur’an 2:127", tags:["Quranic", "Rabbana", "Qabooliyat"], ent:"Dua for Acceptance", enm:"Our Lord, accept this from us. Indeed You are the All-Hearing, the All-Knowing."},
  {cat:'Rabbana', title:"Islam Par Qaim Rehne Ki Dua", arabic:"رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَیۡنِ لَکَ وَمِن ذُرِّیَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّکَ وَأَرِنَا مَنَاسِکَنَا وَتُبۡ عَلَیۡنَآۖ إِنَّکَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِیمُ", translit:"Rabbana waj'alna muslimaini laka wa min zurriyyatina ummatam muslimatal laka wa arina manasikana wa tub 'alayna innaka antat Tawwabur Raheem", meaning:"Ae hamare Rab, humein apna farmabardar bana aur hamari aulad mein se bhi apni farmabardar ummat paida kar. Humein hamare ibadat ke tareeqe dikha aur hamari tauba qabool kar. Beshak Tu tauba qabool karne wala, meherbaan hai.", ref:"Qur’an 2:128", tags:["Quranic", "Rabbana", "Islam"], ent:"Dua to Remain Upon Islam", enm:"Our Lord, make us Muslims, submitting to You, and from our descendants a Muslim nation submitting to You. Show us our rites and accept our repentance. Indeed, You are the Accepting of Repentance, the Merciful."},
  {cat:'Rabbana', title:"Duniya Aur Aakhirat Ki Bhalai", arabic:"رَبَّنَآ ءَاتِنَا فِی ٱلدُّنۡیَا حَسَنَةٗ وَفِی ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana atina fid dunya hasanatanw wa fil akhirati hasanatanw wa qina 'adhaban Nar", meaning:"Ae hamare Rab, humein duniya mein bhalai de aur aakhirat mein bhi bhalai de, aur humein aag ke azaab se bacha le.", ref:"Qur’an 2:201", tags:["Quranic", "Rabbana", "Duniya Aur Aakhirat"], ent:"Good in This World and the Next", enm:"Our Lord, give us good in this world and good in the Hereafter, and save us from the punishment of the Fire."},
  {cat:'Rabbana', title:"Sabr Aur Sabit Qadmi Ki Dua", arabic:"رَبَّنَآ أَفۡرِغۡ عَلَیۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَی ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana afrigh 'alayna sabranw wa thabbit aqdamana wansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hum par sabr undel de, hamare qadam jamaye rakh aur kafir qaum par hamari madad kar.", ref:"Qur’an 2:250", tags:["Quranic", "Rabbana", "Sabr"], ent:"Dua for Patience and Victory", enm:"Our Lord, pour upon us patience, plant our feet firmly, and give us victory over the disbelieving people."},
  {cat:'Rabbana', title:"Bhool Chook Ki Maafi", arabic:"رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِینَآ أَوۡ أَخۡطَأۡنَاۚ", translit:"Rabbana la tu'akhidhna in nasina aw akhta'na", meaning:"Ae hamare Rab, agar hum bhool jayein ya ghalti kar baithein to hamari pakad na kar.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Tauba"], ent:"Forgiveness for Forgetting and Mistakes", enm:"Our Lord, do not hold us accountable if we forget or make mistakes."},
  {cat:'Rabbana', title:"Bhari Bojh Se Hifazat", arabic:"رَبَّنَا وَلَا تَحۡمِلۡ عَلَیۡنَآ إِصۡرٗا کَمَا حَمَلۡتَهُۥ عَلَی ٱلَّذِینَ مِن قَبۡلِنَاۚ", translit:"Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina", meaning:"Ae hamare Rab, hum par woh bojh na daal jo Tu ne hum se pehle logon par daala tha.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Protection from Heavy Burdens", enm:"Our Lord, lay not upon us a burden like that which You laid upon those before us."},
  {cat:'Rabbana', title:"Taqat Se Zyada Imtihan Na Ho", arabic:"رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَیٰنَا فَٱنصُرۡنَا عَلَی ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, anta mawlana fansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hum par utna bojh na daal jitni humein taqat na ho. Humein maaf kar, bakhsh de aur hum par reham kar. Tu hi hamara Maula (kaarsaaz) hai, to kafir qaum par hamari madad kar.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Maghfirat"], ent:"Dua Not to Be Tested Beyond Our Strength", enm:"Our Lord, burden us not with what we have no ability to bear. Pardon us, forgive us and have mercy on us. You are our Protector, so give us victory over the disbelieving people."},
  {cat:'Rabbana', title:"Dil Ko Haq Par Qaim Rakh", arabic:"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَیۡتَنَا وَهَبۡ لَنَا مِن لَّدُنکَ رَحۡمَةًۚ إِنَّکَ أَنتَ ٱلۡوَهَّابُ", translit:"Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka antal Wahhab", meaning:"Ae hamare Rab, hidayat dene ke baad hamare dilon ko seedhe raste se mat phera, aur apni taraf se hum par rehmat farma. Beshak Tu hi bahut ata karne wala hai.", ref:"Qur’an 3:8", tags:["Quranic", "Rabbana", "Hidayat"], ent:"Keep Our Hearts on the Truth", enm:"Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself. Indeed, You are the Bestower."},
  {cat:'Rabbana', title:"Qiyamat Par Yaqeen Ki Dua", arabic:"رَبَّنَآ إِنَّکَ جَامِعُ ٱلنَّاسِ لِیَوْمٍ لَّا رَیْبَ فِیهِ ۚ إِنَّ ٱللَّهَ لَا یُخْلِفُ ٱلْمِیعَادَ", translit:"Rabbana innaka jami'un-nasi liyawmil la raiba fih, innal laha la yukhliful mi'ad", meaning:"Ae hamare Rab, beshak Tu hi tamam logon ko us din ke liye jama karega jis mein koi shak nahi. Beshak Allah apna wada khilaf nahi karta.", ref:"Qur’an 3:9", tags:["Quranic", "Rabbana", "Qiyamat"], ent:"Faith in the Day of Judgment", enm:"Our Lord, indeed You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise."},
  {cat:'Rabbana', title:"Iman Aur Gunahon Ki Maafi", arabic:"رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana innana amanna faghfir lana dhunubana wa qina 'adhaban Nar", meaning:"Ae hamare Rab, hum emaan le aaye hain, to hamare gunah bakhsh de aur hamein aag ke azaab se bacha le.", ref:"Qur’an 3:16", tags:["Quranic", "Rabbana", "Maghfirat"], ent:"Forgiveness of Sins for Believers", enm:"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire."},
  {cat:'Rabbana', title:"Gawahi Mein Shamil Hone Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱکۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ", translit:"Rabbana amanna bima anzalta wattaba'nar Rasula faktubna ma'ash shahidin", meaning:"Ae hamare Rab, hum emaan laaye us par jo Tu ne nazil kiya aur Rasool ki pairwi ki, to hamein gawahon ke saath likh le.", ref:"Qur’an 3:53", tags:["Quranic", "Rabbana", "Iman"], ent:"Dua to Be Among the Witnesses", enm:"Our Lord, we have believed in what You revealed and followed the Messenger, so register us among the witnesses."},
  {cat:'Rabbana', title:"Gunah Aur Hadd Se Barhi Zyadati Ki Maafi", arabic:"رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِیٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَی ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana ghfir lana dhunubana wa israfana fi amrina wa thabbit aqdamana wansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hamare gunah aur hamare kaamon mein hui hadd se barhi zyadatiyan bakhsh de, hamare qadam jamaye rakh aur kafir qaum par hamari madad kar.", ref:"Qur’an 3:147", tags:["Quranic", "Rabbana", "Maghfirat"], ent:"Forgiveness of Sins and Excesses", enm:"Our Lord, forgive us our sins and the excesses in our affairs, plant our feet firmly, and give us victory over the disbelieving people."},
  {cat:'Rabbana', title:"Kainat Ki Hikmat Aur Jahannam Se Panah", arabic:"رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَکَ فَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana ma khalqta hadha batila, subhanaka faqina 'adhaban Nar", meaning:"Ae hamare Rab, Tu ne yeh sab kuch bekaar paida nahi kiya. Tu paak hai, to hamein aag ke azaab se bacha le.", ref:"Qur’an 3:191", tags:["Quranic", "Rabbana", "Jahannam"], ent:"Wisdom of Creation and Protection from Hell", enm:"Our Lord, You did not create this aimlessly. Exalted are You; protect us from the punishment of the Fire."},
  {cat:'Rabbana', title:"Ruswai Se Panah Ki Dua", arabic:"رَبَّنَآ إِنَّکَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَیۡتَهُۥۖ وَمَا لِلظَّٰلِمِینَ مِنۡ أَنصَارٖ", translit:"Rabbana innaka man tudkhilin Nara faqad akhzaytah, wa ma lizzalimina min ansar", meaning:"Ae hamare Rab, beshak jisko Tu aag mein daakhil kare, usay Tu ne rusva kar diya. Zalimon ke liye koi madadgar nahi.", ref:"Qur’an 3:192", tags:["Quranic", "Rabbana", "Jahannam"], ent:"Protection from Disgrace", enm:"Our Lord, indeed whoever You admit to the Fire, You have disgraced him, and for the wrongdoers there are no helpers."},
  {cat:'Rabbana', title:"Pukarne Wale Ki Pukaar Par Iman", arabic:"رَبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِیٗا یُنَادِی لِلۡإِیمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّکُمۡ فَـَٔامَنَّاۚ", translit:"Rabbana innana sami'na munadiyany yunadi lil iymani an aminu bi rabbikum fa amanna", meaning:"Ae hamare Rab, hum ne ek pukarne wale ko suna jo iman ki taraf bula raha tha ki apne Rab par emaan lao, to hum emaan le aaye.", ref:"Qur’an 3:193", tags:["Quranic", "Rabbana", "Iman"], ent:"Faith in the Caller's Call", enm:"Our Lord, indeed we heard a caller calling to faith, saying, 'Believe in your Lord,' and we believed."},
  {cat:'Rabbana', title:"Gunahon Ki Safai Aur Nek Logon Ke Saath Maut", arabic:"رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَکَفِّرۡ عَنَّا سَیِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ", translit:"Rabbana faghfir lana dhunubana wa kaffir 'anna sayyi'atina wa tawaffana ma'al abrar", meaning:"Ae hamare Rab, hamare gunah bakhsh de, hamari burayiyan mita de aur hamein nek logon ke saath maut de.", ref:"Qur’an 3:193", tags:["Quranic", "Rabbana", "Nek Log"], ent:"Cleansing of Sins and a Righteous End", enm:"Our Lord, forgive us our sins, remove from us our misdeeds, and cause us to die with the righteous."},
  {cat:'Rabbana', title:"Wade Ki Pooran Ki Dua, Qiyamat Ki Ruswai Se Bachao", arabic:"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَیٰ رُسُلِکَ وَلَا تُخۡزِنَا یَوۡمَ ٱلۡقِیَٰمَةِۗ إِنَّکَ لَا تُخۡلِفُ ٱلۡمِیعَادَ", translit:"Rabbana wa atina ma wa'attana 'ala rusulika wa la tukhzina yawmal qiyamah, innaka la tukhlifu al-mi'ad", meaning:"Ae hamare Rab, jo wada Tu ne apne Rasoolon ke zariye kiya hai woh hamein ata kar aur qiyamat ke din hamein ruswa na kar. Beshak Tu wade ke khilaf nahi karta.", ref:"Qur’an 3:194", tags:["Quranic", "Rabbana", "Qiyamat"], ent:"Protection from Disgrace on the Day of Judgment", enm:"Our Lord, grant us what You promised through Your messengers, and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in Your promise."},
  {cat:'Rabbana', title:"Gawahi Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا فَٱکۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ", translit:"Rabbana amanna faktubna ma'ash shahidin", meaning:"Ae hamare Rab, hum emaan le aaye, to hamein gawahon mein likh le.", ref:"Qur’an 5:83", tags:["Quranic", "Rabbana", "Iman"], ent:"Dua to Be Among the Witnesses", enm:"Our Lord, we have believed, so register us among the witnesses."},
  {cat:'Rabbana', title:"Rizq Ki Dua (Dastarkhwan)", arabic:"رَبَّنَآ أَنزِلۡ عَلَیۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَکُونُ لَنَا عِیدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَایَةٗ مِّنکَۖ وَٱرۡزُقۡنَا وَأَنتَ خَیۡرُ ٱلرَّٰزِقِینَ", translit:"Rabbana anzil 'alayna ma'idatam minas sama'i takunu lana 'idal li awwalina wa akhirina wa ayatan minka warzuqna wa anta khayrur raziqin", meaning:"Ae hamare Rab, hum par aasmaan se khaane ka dastarkhwan utaar, jo hamare liye, hamare pehlon aur baad waalon ke liye eid ho aur Teri taraf se ek nishani ho. Hamein rizq de, Tu behtareen rizq dene wala hai.", ref:"Qur’an 5:114", tags:["Quranic", "Rabbana", "Rizq"], ent:"Dua for Provision", enm:"Our Lord, send down to us a table spread from the heaven, to be a festival for the first and last of us and a sign from You. Provide for us, and You are the best of providers."},
  {cat:'Rabbana', title:"Apne Nafs Par Zulm Ka Iqrar", arabic:"رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَکُونَنَّ مِنَ ٱلۡخَٰسِرِینَ", translit:"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal khasirin", meaning:"Ae hamare Rab, hum ne apni jaanon par zulm kiya. Agar Tu hamein maaf na kare aur hum par reham na kare to hum yaqeenan nuqsan uthane walon mein se honge.", ref:"Qur’an 7:23", tags:["Quranic", "Rabbana", "Tauba"], ent:"Admitting Our Wrongs (Dua of Adam AS)", enm:"Our Lord, we have wronged ourselves. If You do not forgive us and have mercy upon us, we will surely be among the losers."},
  {cat:'Rabbana', title:"Zalim Logon Ki Sohbat Se Panah", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ", translit:"Rabbana la taj'alna ma'al qawmiz zalimin", meaning:"Ae hamare Rab, hamein zalim logon ke saath shumar na kar.", ref:"Qur’an 7:47", tags:["Quranic", "Rabbana", "Sohbat"], ent:"Protection from the Company of Wrongdoers", enm:"Our Lord, do not place us among the wrongdoing people."},
  {cat:'Rabbana', title:"Haq Ke Saath Faisla", arabic:"رَبَّنَا ٱفۡتَحۡ بَیۡنَنَا وَبَیۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَیۡرُ ٱلۡفَٰتِحِینَ", translit:"Rabbana iftah bayna wa bayna qawmina bil haqqi wa anta khayrul fatihin", meaning:"Ae hamare Rab, hamare aur hamari qaum ke darmiyan haq ke saath faisla kar de, aur Tu behtareen faisla karne wala hai. (Hazrat Shuaib AS ki dua)", ref:"Qur’an 7:89", tags:["Quranic", "Rabbana", "Haq"], ent:"Judgment in Truth (Dua of Shuaib AS)", enm:"Our Lord, decide between us and our people in truth, and You are the best of those who decide."},
  {cat:'Rabbana', title:"Sabr Aur Iman Par Maut", arabic:"رَبَّنَآ أَفۡرِغۡ عَلَیۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِینَ", translit:"Rabbana afrigh 'alayna sabranw wa tawaffana muslimin", meaning:"Ae hamare Rab, hum par sabr undel de aur hamein musalman hone ki haalat mein maut de. (Hazrat Musa AS ki dua)", ref:"Qur’an 7:126", tags:["Quranic", "Rabbana", "Sabr"], ent:"Patience and a Muslim End (Dua of Musa AS)", enm:"Our Lord, pour upon us patience and let us die as Muslims."},
  {cat:'Rabbana', title:"Zalim Qaum Ke Fitne Se Nijaat", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ وَنَجِّنَا بِرَحۡمَتِکَ مِنَ ٱلۡقَوۡمِ ٱلۡکَٰفِرِینَ", translit:"Rabbana la taj'alna fitnatal lil qawmiz zalimin, wa najjina bi rahmatika minal qawmil kafirin", meaning:"Ae hamare Rab, hamein zalim qaum ke liye fitna na bana, aur apni rehmat se hamein kafir qaum se nijaat de.", ref:"Qur’an 10:85-86", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Rescue from an Unjust People", enm:"Our Lord, make us not a trial for the wrongdoing people, and save us by Your mercy from the disbelieving people."},
  {cat:'Rabbana', title:"Allah Se Kuch Chhupa Nahi", arabic:"رَبَّنَآ إِنَّکَ تَعۡلَمُ مَا نُخۡفِی وَمَا نُعۡلِنُۗ وَمَا یَخۡفَیٰ عَلَی ٱللَّهِ مِن شَیۡءٖ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَآءِ", translit:"Rabbana innaka ta'lamu ma nukhfi wa ma nu'lin, wa ma yakhfa 'alal lahi min shay'in fil ardi wa la fis sama'", meaning:"Ae hamare Rab, beshak Tu jaanta hai jo hum chhupate hain aur jo zahir karte hain. Zameen aur aasmaan mein koi cheez Allah se chhupi nahi.", ref:"Qur’an 14:38", tags:["Quranic", "Rabbana", "Ilm-e-Ilahi"], ent:"Nothing Is Hidden from Allah", enm:"Our Lord, You know what we conceal and what we declare, and nothing is hidden from Allah on earth or in heaven."},
  {cat:'Rabbana', title:"Namaz Qaim Karne Ki Dua (Hazrat Ibrahim AS)", arabic:"رَبِّ ٱجۡعَلۡنِی مُقِیمَ ٱلصَّلَوٰةِ وَمِن ذُرِّیَّتِیۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ", translit:"Rabbij 'alni muqimas salati wa min dhurriyyati, Rabbana wa taqabbal du'a", meaning:"Ae mere Rab, mujhe namaz qaim karne wala bana, aur meri aulad mein se bhi. Ae hamare Rab, meri dua qabool kar.", ref:"Qur’an 14:40", tags:["Quranic", "Rabbana", "Namaz"], ent:"Dua to Establish Prayer (Ibrahim AS)", enm:"My Lord, make me one who establishes prayer, and some of my descendants. Our Lord, accept my supplication."},
  {cat:'Rabbana', title:"Maghfirat Walidain Aur Momineen Ke Liye", arabic:"رَبَّنَا ٱغۡفِرۡ لِی وَلِوَٰلِدَیَّ وَلِلۡمُؤۡمِنِینَ یَوۡمَ یَقُومُ ٱلۡحِسَابُ", translit:"Rabbanagh-fir li wa li walidayya wa lil mu'minina yawma yaqumul hisab", meaning:"Ae hamare Rab, mujhe, mere walidain aur tamam momin logon ko us din bakhsh de jis din hisaab qaim hoga.", ref:"Qur’an 14:41", tags:["Quranic", "Rabbana", "Walidain"], ent:"Forgiveness for Parents and Believers", enm:"Our Lord, forgive me, my parents, and the believers on the Day the account is established."},
  {cat:'Rabbana', title:"Rehmat Aur Hidayat Ki Dua (Ashab-e-Kahf)", arabic:"رَبَّنَآ ءَاتِنَا مِن لَّدُنکَ رَحۡمَةٗ وَهَیِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا", translit:"Rabbana atina min ladunka rahmatan wa hayyi' lana min amrina rashada", meaning:"Ae hamare Rab, hamein apni taraf se rehmat ata kar aur hamare kaam mein hamein seedha raasta (hidayat) de. (Ashab-e-Kahf ki dua)", ref:"Qur’an 18:10", tags:["Quranic", "Rabbana", "Hidayat"], ent:"Mercy and Guidance (People of the Cave)", enm:"Our Lord, grant us mercy from Yourself and prepare for us right guidance in our affair."},
  {cat:'Rabbana', title:"Zulm Aur Sarkashi Ka Khauf", arabic:"رَبَّنَآ إِنَّنَا نَخَافُ أَن یَفۡرُطَ عَلَیۡنَآ أَوۡ أَن یَطۡغَیٰ", translit:"Rabbana innana nakhafu an yafruta 'alayna aw an yatgha", meaning:"Ae hamare Rab, hamein darr hai ki woh hum par jaldi saza na kar de ya sarkashi na kare. (Hazrat Harun aur Musa AS ki dua)", ref:"Qur’an 20:45", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Fear of Oppression and Transgression", enm:"Our Lord, we fear that He may hasten punishment against us, or that he may transgress."},
  {cat:'Rabbana', title:"Maghfirat Aur Reham Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَیۡرُ ٱلرَّٰحِمِینَ", translit:"Rabbana amanna faghfir lana warhamna wa anta khayrur rahimin", meaning:"Ae hamare Rab, hum emaan laaye, to hamein bakhsh de aur hum par reham kar, aur Tu sab se behtar reham karne wala hai.", ref:"Qur’an 23:109", tags:["Quranic", "Rabbana", "Rehmat"], ent:"Forgiveness and Mercy", enm:"Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful."},
  {cat:'Rabbana', title:"Jahannam Ke Azaab Se Panah", arabic:"رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا کَانَ غَرَامًا إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا", translit:"Rabbana isrif 'anna 'adhaba jahannam, inna 'adhabaha kana gharama, innaha sa'at mustaqarranw wa muqama", meaning:"Ae hamare Rab, humse Jahannam ka azaab door rakh. Beshak uska azaab laazmi aur chipakne wala hai. Woh bura thikana aur theharne ki jagah hai.", ref:"Qur’an 25:65-66", tags:["Quranic", "Rabbana", "Jahannam"], ent:"Protection from the Punishment of Hell", enm:"Our Lord, avert from us the punishment of Hell. Its punishment is ever adhering; it is evil as a settlement and residence."},
  {cat:'Rabbana', title:"Aankhon Ki Thandak, Nek Aulad Aur Imam", arabic:"رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّیَّـٰتِنَا قُرَّةَ أَعۡیُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِینَ إِمَامًا", translit:"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil muttaqina imama", meaning:"Ae hamare Rab, hamein hamari biwiyon aur aulad se aankhon ki thandak ata kar aur hamein mutteqi logon ka imam (rehnumaa) bana.", ref:"Qur’an 25:74", tags:["Quranic", "Rabbana", "Aulad"], ent:"Comfort to the Eyes and Righteous Leadership", enm:"Our Lord, grant us from our spouses and offspring comfort to our eyes, and make us a leader for the righteous."},
  {cat:'Rabbana', title:"Shukr Aur Bakhshish", arabic:"رَبَّنَا لَغَفُورٌ شَکُورٌ", translit:"Rabbana la ghafurun shakur", meaning:"Ae hamare Rab, beshak Tu bakhshne wala aur qadar karne wala hai.", ref:"Qur’an 35:34", tags:["Quranic", "Rabbana", "Shukr"], ent:"Forgiveness and Appreciation", enm:"Our Lord is Forgiving and Appreciative."},
  {cat:'Rabbana', title:"Tauba Karne Walon Ki Maghfirat Aur Jahannam Se Hifazat", arabic:"رَبَّنَا وَسِعۡتَ کُلَّ شَیۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِینَ تَابُواْ وَٱتَّبَعُواْ سَبِیلَکَ وَقِهِمۡ عَذَابَ ٱلۡجَحِیمِ", translit:"Rabbana wasi'ta kulla shay'in rahmatanw wa 'ilman faghfir lilladhina taabu wattaba'u sabilaka wa qihim 'adhabal jahim", meaning:"Ae hamare Rab, Tu ne har cheez ko apni rehmat aur ilm mein samoya hua hai. Un logon ko bakhsh de jo tauba karte hain aur Tere raaste ki pairwi karte hain, aur unhein jahannam ke azaab se bacha le.", ref:"Qur’an 40:7", tags:["Quranic", "Rabbana", "Tauba"], ent:"Forgiveness for Those Who Repent", enm:"Our Lord, You have encompassed all things in mercy and knowledge. Forgive those who repent and follow Your way, and protect them from the punishment of Hellfire."},
  {cat:'Rabbana', title:"Jannat Mein Walidain, Aulad Aur Biwiyon Ke Saath", arabic:"رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِی وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّیَّـٰتِهِمۡۚ إِنَّکَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَکِیمُ وَقِهِمُ ٱلسَّیِّـَٔاتِۚ وَمَن تَقِ ٱلسَّیِّـَٔاتِ یَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِکَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ", translit:"Rabbana wa adkhilhum jannati 'adnin allati wa'attahum wa man salaha min aba'ihim wa azwajihim wa dhurriyyatihim, innaka antal 'Azizul Hakim. Wa qihimus sayyi'at, wa man taqis sayyi'ati yawma'idhin faqad rahimtah, wa dhalika huwal fawzul 'adhim", meaning:"Ae hamare Rab, unhein Adan ke baghon mein daakhil kar jo Tu ne unse wada kiya hai, aur unke baap-dada, biwiyon aur aulad mein se jo nek hain unhein bhi. Beshak Tu hi zabardast aur hikmat wala hai. Unhein buraiyon se bacha, aur jisko Tu us din buraiyon se bacha le, us par Tu ne reham kiya. Yehi badi kamyabi hai.", ref:"Qur’an 40:8-9", tags:["Quranic", "Rabbana", "Jannat"], ent:"Paradise with Family", enm:"Our Lord, admit them to gardens of perpetual residence which You promised them, along with the righteous among their forefathers, spouses and offspring. Protect them from evil consequences. That is the great success."},
  {cat:'Rabbana', title:"Bhai Bandon Ke Liye Maghfirat, Dil Mein Kina Na Ho", arabic:"رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِینَ سَبَقُونَا بِٱلۡإِیمَٰنِ وَلَا تَجۡعَلۡ فِی قُلُوبِنَا غِلّٗا لِّلَّذِینَ ءَامَنُواْ", translit:"Rabbana ghfir lana wa li ikhwanina alladhina sabaquna bil iman, wa la taj'al fi qulubina ghillal lilladhina amanu", meaning:"Ae hamare Rab, hamein aur hamare un bhaiyon ko bakhsh de jo hum se pehle emaan laaye, aur hamare dilon mein emaan walon ke liye kina na rakh.", ref:"Qur’an 59:10", tags:["Quranic", "Rabbana", "Ukhuwwat"], ent:"Brotherhood Without Resentment", enm:"Our Lord, forgive us and our brothers who preceded us in faith, and put not in our hearts resentment toward those who believed."},
  {cat:'Rabbana', title:"Rauf Aur Raheem Rab Ki Pukaar", arabic:"رَبَّنَآ إِنَّکَ رَءُوفٞ رَّحِیمٞ", translit:"Rabbana innaka ra'ufur rahim", meaning:"Ae hamare Rab, beshak Tu bahut shafqat karne wala aur reham karne wala hai.", ref:"Qur’an 59:10", tags:["Quranic", "Rabbana", "Rehmat"], ent:"Dua of Kindness and Mercy", enm:"Our Lord, indeed You are Kind and Merciful."},
  {cat:'Rabbana', title:"Tawakkul Aur Akhirat Ki Taraf Wapsi", arabic:"رَّبَّنَا عَلَیۡکَ تَوَکَّلۡنَا وَإِلَیۡکَ أَنَبۡنَا وَإِلَیۡکَ ٱلۡمَصِیرُ", translit:"Rabbana 'alayka tawakkalna wa ilayka anabna wa ilaykal masir", meaning:"Ae hamare Rab, hamne Tujh par tawakkul kiya, Teri taraf rujoo kiya aur Teri hi taraf lautna hai.", ref:"Qur’an 60:4", tags:["Quranic", "Rabbana", "Tawakkul"], ent:"Trust in Allah and Return to Him", enm:"Our Lord, upon You we have relied, to You we have returned, and to You is the destination."},
  {cat:'Rabbana', title:"Kafiron Ke Fitne Se Hifazat (Hazrat Ibrahim AS)", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِینَ کَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّکَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَکِیمُ", translit:"Rabbana la taj'alna fitnatal lilladhina kafaru waghfir lana rabbana, innaka antal 'Azizul Hakim", meaning:"Ae hamare Rab, hamein kafiron ke liye fitna (aazmaish ka zariya) na bana, aur hamein bakhsh de. Beshak Tu zabardast aur hikmat wala hai.", ref:"Qur’an 60:5", tags:["Quranic", "Rabbana", "Hifazat"], ent:"Protection from the Trial of Disbelievers (Ibrahim AS)", enm:"Our Lord, make us not a trial for the disbelievers, and forgive us. Indeed, You are the Exalted in Might, the Wise."},
  {cat:'Rabbana', title:"Noor Ki Takmeel Aur Maghfirat", arabic:"رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّکَ عَلَیٰ کُلِّ شَیۡءٖ قَدِیرٞ", translit:"Rabbana atmim lana nurana waghfir lana, innaka 'ala kulli shay'in qadir", meaning:"Ae hamare Rab, hamare liye hamara noor mukammal kar de aur hamein bakhsh de. Beshak Tu har cheez par qadir hai.", ref:"Qur’an 66:8", tags:["Quranic", "Rabbana", "Noor"], ent:"Completion of Our Light and Forgiveness", enm:"Our Lord, perfect our light for us and forgive us. Indeed, You are over all things competent."},
  {cat:"Pareshani", title:"Gham, Susti Aur Qarz Se Panah Ki Dua", arabic:"اللَّهُمَّ إِنِّی أَعُوذُ بِکَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِکَ مِنَ الْعَجْزِ وَالْکَسَلِ، وَأَعُوذُ بِکَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِکَ مِنْ غَلَبَةِ الدَّیْنِ وَقَهْرِ الرِّجَالِ", translit:"Allahumma inni a'udhu bika minal-hammi wal-hazan, wa a'udhu bika minal-'ajzi wal-kasal, wa a'udhu bika minal-jubni wal-bukhl, wa a'udhu bika min ghalabatid-dayni wa qahrir-rijal.", meaning:"Ya Allah! Main Tujh se fikr aur gham se panah maangta hoon, aur be-basi aur susti se panah maangta hoon. Main Tujh se buzdili aur bukhl se panah maangta hoon, aur qarz ke bojh aur logon ke ghalib aa jane se Teri panah chahta hoon.", ref:"Sahih Bukhari", tags:["Sunnah", "Pareshani", "Hifazat"], ent:"Protection from Worry, Weakness and Debt", enm:"O Allah, I seek refuge in You from worry and grief, from weakness and laziness, from cowardice and miserliness, and from being overcome by debt and overpowered by men."},
  {cat:"Khana", title:"Khana khatam hone ki dua", arabic:"الْحَمْدُ لِلَّهِ الَّذِی أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مِنَ الْمُسْلِمِینَ", translit:"Alhamdu lillahil-lazi at'amana wa saqana wa ja'alana minal muslimin.", meaning:"Sab khubiyan Allah paak ke liye hain, jisne hamein khilaya aur pilaya aur musalman banaya.", ref:"Abu Dawood, Tirmidhi", info:"Hadees: Hazrat Abu Sa'eed Khudri (RA) se riwayat hai ki Nabi ﷺ ne farmaya: jo shakhs khana khane ke baad yeh dua padhe, uske pichle gunah bakhsh diye jayenge. Khana khatam karne ke baad shukr ka izhaar karna sunnat hai.", tags:["Sunnah", "Shukr"], ent:"Dua After Finishing Food", enm:"All praise is for Allah, who fed us, gave us drink, and made us Muslims.", eninfo:"Hadith: Abu Sa'eed Khudri (RA) narrated that the Prophet ﷺ said: whoever says this dua after eating, his past sins will be forgiven. Expressing gratitude after finishing a meal is a Sunnah."},
];
const HADEES = [
  {cat:'Namaz', src:'Sahih Bukhari', txt:'Namaz Deen ka sutoon hai. Jisne isko qayam kiya usne Deen ko qayam kiya, aur jisne isko chhod diya usne Deen ko gira diya.', en:"Establishing prayer is the pillar of the religion. Whoever establishes it has established the religion, and whoever abandons it has destroyed the religion."},
  {cat:'Namaz', src:'Sahih Muslim', txt:'Qayamat ke din banda ke aamaal mein sabse pehle Namaz ka hisaab liya jayega. Agar woh theek hui to baaki sab aamaal theek honge.', en:"On the Day of Judgment, the first deed a servant will be questioned about is prayer. If it is sound, the rest of his deeds will be sound."},
  {cat:'Akhlaq', src:'Sahih Bukhari', txt:'Tum mein sabse behtareen woh hai jo apne akhlaq mein sabse achha ho.', en:"The best of you is the one with the best character."},
  {cat:'Akhlaq', src:'Tirmidhi', txt:'Musalman woh hai jiski zabaan aur haath se doosre Musalman mehfooz rahein.', en:"A Muslim is the one from whose tongue and hand other Muslims are safe."},
  {cat:'Ilm', src:'Ibn Majah', txt:'Ilm haasil karna har Musalman mard aur aurat par farz hai.', en:"Seeking knowledge is an obligation upon every Muslim, man and woman."},
  {cat:'Sadqa', src:'Sahih Bukhari', txt:'Muskuraana bhi sadqa hai.', en:"Smiling is also charity."},
  {cat:'Ramzan', src:'Sahih Bukhari', txt:'Jab Ramzan aata hai to Jannat ke darwaze khol diye jaate hain aur Jahannam ke darwaze band kar diye jaate hain.', en:"When Ramadan comes, the gates of Paradise are opened, the gates of Hell are closed, and the devils are chained."},
  {cat:'Ramzan', src:'Sahih Muslim', txt:'Jisne Ramzan ke roze imaan ke saath aur sawaab ki niyyat se rakhe, uske pichhle gunaah maaf kar diye jaate hain.', en:"Whoever fasts Ramadan with faith and seeking its reward, his past sins will be forgiven."},
];

