const AADAAB_TOPICS = [
  { id:"bas-5-minute-ka-jhoot", title:"'Bas 5 Minute' Ka Jhoot", tags:["Waqt","Phone","Zimmedari"], ic:"⏱️", cat:"waqt", color:"#c79a2e",
    en:{"title": "The 'Just 5 Minutes' Lie", "tags": ["Time", "Phone", "Responsibility"], "scene": "Opened the phone, watched one reel, then another, then a third. 'Just 5 minutes', and an hour was gone.", "masla": "We protect time as if it were money, but time is even more limited than money. Once it passes, it never comes back.", "islam": "Keeping an account of your time and not wasting it on pointless things is wisdom.", "nabi": null, "galti": "We think, 'What difference will 5 minutes make?' But these 5 minutes add up to hours every day.", "tabdeeli": "The next time you open an app for just 5 minutes, set a timer and see how much time it really takes."},
    scene:"Phone khola, ek reel dekhi, phir doosri, phir teesri, 'bas 5 minute' kehte kehte ek ghanta nikal gaya.",
    masla:"Hum waqt ko paisa samajh kar protect karte hain, lekin waqt paison se bhi zyada limited hai, ek baar guzar jaaye toh wapas nahi aata.",
    islam:"Apne waqt ka hisaab rakhna aur usay fuzool kaamon mein zaya na karna aqalmandi hai.",
    nabi:null,
    galti:"Hum sochte hain '5 minute se kya farq padega', lekin yehi 5 minute roz kai ghanton mein badal jaate hain.",
    tabdeeli:"Jab kisi app ko sirf 5 minute ke liye kholein, timer laga kar dekhiye ke asal mein kitna waqt ja raha hai." },
  { id:"main-aisa-hi-hoon", title:"'Main Aisa Hi Hoon' Excuse Nahi", tags:["Islah","Shakhsiyat","Koshish"], ic:"🪞", cat:"akhlaq", color:"#5cb85c",
    en:{"title": "'I'm Just Like This' Is Not an Excuse", "tags": ["Reform", "Personality", "Effort"], "scene": "'I have a short temper.' 'I'm never on time.' 'I just talk like this.' 'It's just my nature.'", "masla": "There is a difference between personality and a bad habit. If a habit keeps hurting you or others, calling it 'my nature' to avoid change is avoiding self-improvement.", "islam": "Islam invites a person to improve his character and habits. This is an ongoing effort.", "nabi": null, "galti": "We treat our habits as a fixed personality, so we stop trying to change them at all.", "tabdeeli": "Identify one habit that hurts others. Instead of saying 'it's my nature', make an effort to improve it."},
    scene:"'Main gusse wala hoon.' 'Main punctual nahi hoon.' 'Main aisa hi bolta hoon.' 'Mera nature hi aisa hai.'",
    masla:"Shakhsiyat aur buri aadat mein farq hai. Agar koi aadat aapko ya doosron ko musalsal takleef de rahi hai, toh usay 'mera nature' kehkar bachaav karna khud-islahi se bachna hai.",
    islam:"Islam insan ko apne akhlaaq aur aadaat ko behtar banane ki dawat deta hai, yeh ek jaari rehne wala amal hai.",
    nabi:null,
    galti:"Hum apni aadaton ko 'fixed personality' samajh kar unko badalne ki koshish hi chhod dete hain.",
    tabdeeli:"Apni ek aisi aadat identify kijiye jo doosron ko takleef deti hai, aur usay 'mera nature hai' kehne ke bajaye behtar banane ki koshish kijiye." },
  { id:"aaram-sustee-farq", title:"Aaram Aur Sustee Mein Farq Hai", tags:["Rest","Zimmedari","Self-Care"], ic:"🛌", cat:"sehat", color:"#e0893f",
    en:{"title": "Rest and Laziness Are Different", "tags": ["Rest", "Responsibility", "Self-Care"], "scene": "Tired? Rest. Not enough sleep? Sleep. Does the body need recovery? Take a break. But 'I don't feel like it' and 'I really need rest' are not the same thing.", "masla": "Healthy rest makes you productive again. Laziness keeps you away from your responsibilities, and we forget the difference between the two.", "islam": "Islam teaches us to care for both rest and responsibility: neither to abuse the body, nor to use it as an excuse to abandon work.", "nabi": null, "galti": "We call laziness 'self-care', while real self-care is what makes us better and more responsible.", "tabdeeli": "Keep your rest guilt-free, but do not call your laziness 'self-care'."},
    scene:"Thak gaye hain? Aaram kijiye. Neend poori nahi hui? Soyiye. Body ko recovery chahiye? Rest kijiye. Lekin 'mera mood nahi hai' aur 'mujhe waqai rest chahiye', dono ek cheez nahi.",
    masla:"Healthy rest aapko dobara productive banata hai. Sustee aapko apni zimmedariyon se door karti rehti hai, aur hum dono mein farq karna bhool jaate hain.",
    islam:"Islam mein aaram aur zimmedari dono ka khayal rakhna sikhaya gaya hai, na jism par zulm karna, na usay bahana bana kar kaam chhod dena.",
    nabi:null,
    galti:"Hum susti ko 'self-care' ka naam de dete hain, jabke asal self-care woh hai jo hamein behtar aur zimmedar banaye.",
    tabdeeli:"Apne rest ko guilt-free rakhiye, lekin apni laziness ko 'self-care' ka naam mat dijiye." },
  { id:"allah-sirf-namaz-waqt-nahi", title:"Allah Ko Sirf Namaz Ke Waqt Yaad Na Karein", tags:["Zikr","Taqwa","Rozmarra Ibadat"], ic:"🕋", cat:"ibadat", color:"#9b6fd6",
    en:{"title": "Do Not Remember Allah Only at Prayer Time", "tags": ["Remembrance", "Taqwa", "Daily Worship"], "scene": "Prayer is an obligatory and central act of worship. But should the rest of life be completely disconnected from Allah?", "masla": "Intention while working, gratitude while eating, seeking Allah's pleasure while helping someone, fear of Allah when a wrong opportunity comes, trust in Allah in hardship: these too are part of the Deen.", "islam": "Deen and daily life are not two separate things. Every permissible action done with a good intention can become worship.", "nabi": null, "galti": "We limit Allah to prayer, fasting and the masjid, and keep the rest of life apart from the Deen, thinking of it as 'worldly'.", "tabdeeli": "Today, start one daily task with a good intention, keeping in mind that it too is for Allah."},
    scene:"Namaz apni jagah farz aur markazi ibadat hai. Lekin kya baaki zindagi Allah se bilkul disconnected honi chahiye?",
    masla:"Kaam karte waqt niyyat, khate waqt shukr, kisi ki madad karte waqt Allah ki raza, galat mauka aaye toh Allah ka khauf, kisi mushkil mein Allah par tawakkul, yeh sab bhi Deen ka hissa hain.",
    islam:"Deen aur rozmarra zindagi do alag khaane nahi. Har jaayez kaam agar achhi niyyat se kiya jaaye, toh woh bhi ibadat ban sakta hai.",
    nabi:null,
    galti:"Hum Allah ko sirf namaz, roza aur masjid tak mehdood kar dete hain, aur baaki zindagi ko 'duniyawi' samajh kar Deen se alag rakh dete hain.",
    tabdeeli:"Apne rozmarra ke kisi ek kaam ko aaj achhi niyyat ke saath shuru kijiye, is khayal ke saath ke yeh bhi Allah ke liye hai." },
  { id:"amanat-wapas-kijiye", title:"Amanat Wapas Kijiye", tags:["Amanat","Trust","Zimmedari"], ic:"📦", cat:"maal", color:"#b8860b",
    en:{"title": "Return the Trust (Amanat)", "tags": ["Trust", "Trustworthiness", "Responsibility"], "scene": "A friend lent you a book, a relative gave you money, the office gave you equipment, someone handed you an important document. You kept it and then forgot about it.", "masla": "A trust is not only about big things. Even small things must be treated as a trust.", "islam": "Protecting a trust and returning it on time is a sign of faith.", "nabi": null, "galti": "We think 'I'll give it back when I remember', and then the matter is put off forever.", "tabdeeli": "Look around your home: is there something that belongs to someone else which you have been keeping without reason? Make a plan to return it today."},
    scene:"Friend ne book di, relative ne paisa diya, office ne equipment diya, kisi ne important document aapko diya, aapne rakha aur phir bhool gaye.",
    masla:"Amanat ka matlab sirf badi cheez nahi. Chhoti cheez ko bhi amanat samajhna zaroori hai.",
    islam:"Amanat ki hifazat aur waqt par wapas karna Imaan ki ek nishani hai.",
    nabi:null,
    galti:"Hum sochte hain 'yaad aane par de dunga', aur phir yeh baat hamesha ke liye taal jaati hai.",
    tabdeeli:"Ghar mein dekhiye: kya kisi aur ki koi cheez aapke paas be-wajah padi hui hai? Usay aaj hi wapas karne ka iraada kijiye." },
  { id:"ammi-abbu-baad-mein", title:"Ammi/Abbu Ko 'Baad Mein' Kehte Rehna", tags:["Walidain","Waqt","Husn-e-Sulook"], ic:"👴", cat:"ghar", color:"#d6708f",
    en:{"title": "Telling Mum and Dad 'Later' Again and Again", "tags": ["Parents", "Time", "Good Conduct"], "scene": "'I'm busy.' 'I'll talk later.' 'I'm in a meeting.' 'One minute.' Sometimes parents are only asking for a little of our time.", "masla": "Not every call is urgent, but every relationship needs attention, and the relationship with parents needs it most.", "islam": "Good treatment of parents and respect for them is a very important theme in the Quran.", "nabi": null, "galti": "We think 'they will understand, I'll talk to them later', and that 'later' never comes.", "tabdeeli": "Today, sit with your parents for 10 minutes without a phone."},
    scene:"'Abhi busy hoon.' 'Baad mein baat karta hoon.' 'Abhi meeting hai.' 'Ek minute.' Kabhi parents humse sirf thoda waqt maang rahe hote hain.",
    masla:"Har call urgent nahi hoti, lekin har rishta tawajjo chahta hai, aur waalidain ka rishta sabse zyada.",
    islam:"Walidain ke saath husn-e-sulook aur unki izzat Qur'an ka bohot ahem mauzu hai.",
    nabi:null,
    galti:"Hum sochte hain 'woh samajh jaayenge, main baad mein baat kar lunga', aur yeh 'baad mein' kabhi aata hi nahi.",
    tabdeeli:"Aaj walidain ke saath bina phone ke sirf 10 minute baithiye." },
  { id:"bachon-ko-example-chahiye", title:"Bachon Ko Sirf Lecture Nahi, Example Chahiye", tags:["Tarbiyat","Kirdaar","Walidain"], ic:"🧒", cat:"ghar", color:"#d6708f",
    en:{"title": "Children Need Examples, Not Just Lectures", "tags": ["Upbringing", "Character", "Parents"], "scene": "You tell your child 'use your phone less', and then you are on the phone for six hours. You say 'don't lie', and on the phone you say 'tell them Dad is not at home'.", "masla": "Children observe our behaviour much more than our words, and they learn from it.", "islam": "Parents are the first example for their children. Upbringing comes not only from advice but from one's own actions.", "nabi": null, "galti": "We think 'this rule is only for the child', while children always copy what we actually do.", "tabdeeli": "Whatever habit you want to teach your child, first practise it yourself."},
    scene:"Aap bachche se kehte hain 'phone kam use karo', aur khud 6 ghante phone par. Aap kehte hain 'jhoot nahi bolna', aur phone par kehte hain 'bol dena papa ghar par nahi hain'.",
    masla:"Bachche hamari baatein kam aur hamara rawayya (behaviour) zyada observe karte hain, aur wahi seekhte hain.",
    islam:"Walidain apni aulad ke liye sabse pehla example hote hain; tarbiyat sirf nasihat se nahi, apne amal se hoti hai.",
    nabi:null,
    galti:"Hum sochte hain 'yeh toh sirf bache ke liye rule hai', jabke bachche hamesha hamare amal ko hi copy karte hain.",
    tabdeeli:"Bachche ko jo ek aadat sikhani hai, usay pehle khud apnaiye." },
  { id:"bargain-zulm-nahi", title:"Bargain Karte Waqt Zulm Mat Kijiye", tags:["Insaaf","Tijarat","Haq"], ic:"🤝", cat:"maal", color:"#b8860b",
    en:{"title": "Do Not Oppress While Bargaining", "tags": ["Justice", "Trade", "Rights"], "scene": "An item costs ₹500, and you say 'I'll take it for ₹100'. The seller is forced to agree. You know the price is higher, yet you take full advantage of his need.", "masla": "There is a difference between bargaining and exploitation. Buying cheaply is no achievement if it means taking away someone else's rights.", "islam": "Trade requires the consent and fairness of both sides. Taking unfair advantage of someone's need is forbidden in Islam.", "nabi": null, "galti": "We call this 'smart bargaining', when in fact it becomes taking advantage of someone's need.", "tabdeeli": "When bargaining, ask yourself: 'Is this price fair, or am I just taking advantage of the seller's need?'"},
    scene:"₹500 ki cheez, aapne kaha 'main ₹100 mein lunga'. Seller majboor hai, aapko pata hai item ki qeemat zyada hai, phir bhi uski majboori ka poora fayda uthaya.",
    masla:"Bargaining aur zyadti (exploitation) mein farq hota hai. Sasta khareedna koi achievement nahi agar uske liye kisi aur ka haq dabana pade.",
    islam:"Tijarat mein dono taraf ki raza aur insaaf zaroori hai, kisi ki majboori ka ghalat fayda uthana Islam mein mana hai.",
    nabi:null,
    galti:"Hum isay 'smart bargaining' samajh lete hain, jabke asal mein yeh kisi ki majboori ka istemal ban jaata hai.",
    tabdeeli:"Bargain karte waqt socha kijiye: 'Kya yeh qeemat insaaf wali hai, ya main sirf uski majboori ka fayda utha raha hoon?'" },
  { id:"biwi-shauhar-emotional-dustbin-nahi", title:"Biwi/Shauhar Aapka Emotional Dustbin Nahi", tags:["Rishta","Sabr","Mohabbat"], ic:"💞", cat:"ghar", color:"#d6708f",
    en:{"title": "Your Spouse Is Not Your Emotional Dustbin", "tags": ["Marriage", "Patience", "Love"], "scene": "Stress from the office, anger from traffic, frustration with the boss, financial pressure. And as soon as you get home, you take it out on your spouse. Then: 'But you are my own.'", "masla": "Being close is not a licence to hurt someone. A spouse is a person with whom you build peace and companionship, not someone to dump every frustration on.", "islam": "Gentleness, love and respect for each other in the relationship between husband and wife is an important part of Islamic teaching.", "nabi": "The Prophet ﷺ said: the best of you is the one who is best to his family.", "galti": "We bring outside anger inside, and make our closest relationships the target of it.", "tabdeeli": "Before coming home, recognise your day's stress, and do not make your household the target of it without reason."},
    scene:"Office ka stress, traffic ka gussa, boss ki frustration, financial tension, aur ghar aate hi spouse par nikal diya. Phir: 'Tum toh mere apne ho.'",
    masla:"Apna hona kisi ko takleef pahunchane ka license nahi. Spouse woh insaan hai jiske saath sukoon aur rifaqat banani hai, har frustration dump karne ke liye nahi.",
    islam:"Shauhar aur biwi ke rishte mein narmi, mohabbat aur ek doosre ki qadr karna Islami taleem ka ahem hissa hai.",
    nabi:"Nabi ﷺ ne farmaya ke tum mein behtareen woh hai jo apne ghar walon ke saath behtareen ho.",
    galti:"Hum bahar ka gussa andar le aate hain aur sabse qareebi rishte ko hi uska target bana dete hain.",
    tabdeeli:"Ghar aane se pehle apne din ka stress pehchaniye, aur ghar walon ko bila wajah uska nishana mat banaiye." },
  { id:"bolne-se-pehle-sochiye", title:"Bolne Se Pehle Sochiye", tags:["Guftugu","Khamoshi","Tahammul"], ic:"🤐", cat:"zubaan", color:"#7e6fd6",
    en:{"title": "Think Before You Speak", "tags": ["Speech", "Silence", "Tolerance"], "scene": "Not everything we know needs to be said. Not every opinion needs to be given. Not every argument needs a reply. Not every secret needs to be shared.", "masla": "We often speak simply because we get the chance, without thinking whether it is needed.", "islam": "Using the tongue thoughtfully is a basic part of Islamic etiquette.", "nabi": "The Prophet ﷺ taught: say something good or remain silent (Sahih Bukhari 6475).", "galti": "Sometimes we keep talking just to prove our point, whether or not it is necessary.", "tabdeeli": "Before saying anything, ask yourself three questions: Is it true? Is it necessary? Is it beneficial to someone? If not, silence is the better answer."},
    scene:"Har baat jo hum jaante hain, bolna zaroori nahi. Har opinion dena zaroori nahi. Har argument ka jawab dena zaroori nahi. Har secret share karna zaroori nahi.",
    masla:"Hum aksar sirf isliye bol dete hain kyunke mauka mil gaya, bina yeh socha ke uski zarurat bhi hai ya nahi.",
    islam:"Zaban ka istemal sochh samajh kar karna Islami adab ka bunyadi hissa hai.",
    nabi:"Nabi ﷺ ki taleem hai ke insan achhi baat kahe ya khamosh rahe (Sahih Bukhari 6475).",
    galti:"Hum kabhi-kabhi sirf apni baat sahi sabit karne ke liye bolte rehte hain, chahe woh zaroori ho ya na ho.",
    tabdeeli:"Kisi bhi baat se pehle teen sawal khud se poochiye: kya yeh sach hai? Kya yeh zaroori hai? Kya yeh kisi ke liye faida-mand hai? Agar nahi, toh khamoshi behtar jawab hai." },
  { id:"buffet-muqabala-nahi", title:"Buffet Hai, Muqabala Nahi", tags:["Israf","Aitedaal","Khana"], ic:"🍱", cat:"khana", color:"#c0563f",
    scene:"'Paisa vasool karna hai', isliye plate par 15 items, phir dessert, phir cold drink, phir ice cream. Aur ghar jaakar: 'Aaj toh bahut kha liya.'",
    masla:"Buffet ka purpose choice hai, overeating ka license nahi.",
    islam:"Qur'an ka usool simple hai: khaaiye, peejiye, lekin israf na kijiye.",
    nabi:null,
    galti:"Hum 'paisa vasool' ki soch ko apni sehat se upar rakh dete hain, jabke asal nuqsan apne hi jism ka hota hai.",
    tabdeeli:"Buffet mein pehle poori table dekh lijiye, phir woh cheezein lijiye jo waqai khani hain." },
  { id:"business-mein-sach", title:"Business Mein Sach Bolna", tags:["Diyanat","Tijarat","Amanat"], ic:"🧾", cat:"maal", color:"#b8860b",
    scene:"Product mein defect hai, aapko pata hai lekin customer ko nahi bataya. Photo mein kuch aur, reality mein kuch aur. 'Original' likh diya jab original nahi. Fake urgency: 'Last piece!' jab actually stock full hai.",
    masla:"Business mein profit kamaana jaayez hai, lekin dhoka profit ka substitute nahi ban sakta.",
    islam:"Tijarat mein sach bolna aur maal ka aib chhupa kar na bechna Islami tijarat ke bunyadi usool hain.",
    nabi:"Nabi ﷺ ne farmaya ke sachcha aur amanatdar tajir Qiyamat ke din Anbiya, Siddiqeen aur Shuhada ke saath hoga.",
    galti:"Hum sochte hain 'thoda overpromise karna business ka hissa hai', jabke yeh customer ke trust ke saath dhoka hai.",
    tabdeeli:"Apne agle customer ko product ke baare mein ek aisi sach baat bataiye jo aap normally chhupa dete." },
  { id:"der-se-aana-rawayya", title:"Der Se Aana Bhi Ek Rawayya Hai", tags:["Waqt Ki Pabandi","Doosron Ka Haq","Zimmedari"], ic:"⏰", cat:"waqt", color:"#c79a2e",
    scene:"'Bas 5 minute.' 'Traffic tha.' 'Bas nikal raha hoon.', aur doosra insaan 30 minute se intezar kar raha hai.",
    masla:"Waqt sirf hamara nahi hota. Jab koi hamara intezar kar raha hai, toh uska waqt bhi hamare faisle se mutasir ho raha hai.",
    islam:"Waade ki pabandi aur doosron ke waqt ki izzat karna Islami akhlaaq ka hissa hai.",
    nabi:null,
    galti:"Hum apni derri ko hamesha 'majboori' keh kar justify kar dete hain, jabke zyada tar waqt yeh planning ki kami hoti hai.",
    tabdeeli:"Appointments, meetings, namaz, classes, kaam, har jagah waqt par pahunchne ki koshish kijiye." },
  { id:"tasveer-property-nahi", title:"Dusre Ki Tasveer Aapki Property Nahi", tags:["Permission","Izzat","Digital Adab"], ic:"🖼️", cat:"digital", color:"#5c7cfa",
    scene:"Kisi ki photo mili, kisi ka funny video mila, kisi friend ki embarrassing picture mili, aur foran khayal aaya 'group mein bhej deta hoon'.",
    masla:"Rukiye, kya usne permission di? Digital technology ne photo share karna aasan bana diya hai, lekin permission ki zarurat khatam nahi hui.",
    islam:"Kisi ki izzat aur raza ke bagair uski tasveer ya maloomat istemal karna uske haq ki khilaf-warzi hai.",
    nabi:null,
    galti:"Hum sochte hain 'yeh toh sirf mazaak hai', jabke saamne wale ke liye woh embarrassment ka sabab ban sakta hai.",
    tabdeeli:"Kisi ko embarrass karne ke liye uski tasveer istemal karne se pehle ruk jaiye." },
  { id:"dusron-ka-sadqah", title:"Dusron Ka Sadqah Mat Giniye", tags:["Posheedgi","Ikhlaas","Apne Aamaal"], ic:"🙈", cat:"ibadat", color:"#9b6fd6",
    scene:"Aap masjid mein baithe hain. Bagal mein koi shakhs donation box ki taraf badh raha hai. Aapki nazar khud-ba-khud uske haath ki taraf chali jaati hai, dekhte hain kitna note nikaal raha hai, kitna box mein daal raha hai.",
    masla:"Yahan masla sirf 'dekhna' nahi, balki dil mein chalne wala hisaab hai, 'itna hi diya?' ya 'itna zyada, dikhawa toh nahi?' Jab hum kisi doosre ke sadqe ko tolte hain, toh uske aur Allah ke darmiyan ke maamle mein be-ja dakhal de dete hain, aur apne hi aamaal se ghafil ho jaate hain.",
    islam:"Sadqah ki qadr raqam ki miqdar se nahi, niyyat aur ikhlaas se hoti hai. Har shakhs apne amal ka khud zimmedar hai; Qiyamat ke din bhi har ek se uske apne amal ka hisaab hoga, kisi doosre ke amal ka nahi.",
    nabi:"Nabi ﷺ ne chhup kar sadqah karne ko itna pasand farmaya ke irshad farmaya: jab daahine haath se sadqah karo to baayein haath ko bhi khabar na ho, sadqah sirf Allah ke liye ho, kisi ko dikhane ke liye nahi.",
    galti:"Hum mein se aksar ko yeh ehsaas tak nahi hota ke hum kisi ke sadqe ko gin rahe hain, yeh ek khamoshi se ban jaane wali aadat hai, gunah ki niyyat se nahi, balki tawajjo bhatakne se.",
    tabdeeli:"Agli baar jab koi khamoshi se de raha ho, apni nazrein jhuka lijiye ya apne zikr mein masroof ho jaiye, uske haath ki taraf dekhna chhod dijiye." },
  { id:"dusron-zindagi-mat-khaiye", title:"Dusron Ki Zindagi Ko Mat Khaaiye", tags:["Tajassus","Privacy","Ikhlaas"], ic:"🕵️", cat:"zubaan", color:"#7e6fd6",
    scene:"'Uski salary kitni hai?' 'Uska rent kitna hai?' 'Kitne mein ghar liya?' 'Shaadi mein kitna kharcha hua?' 'Unke ghar mein kya chal raha hai?', har cheez jaan lena zaroori nahi.",
    masla:"Curiosity aur tajassus mein farq hota hai. Kisi ke private maamlaat ko bila wajah khodna uski privacy ka haq cheenna hai.",
    islam:"Qur'an mein tajassus aur bad-gumaani se bachne ki wazeh hidayat di gayi hai (Al-Hujurat 49:12).",
    nabi:null,
    galti:"Hum isay 'bas waise hi pooch liya' keh kar justify kar dete hain, jabke saamne wale ko woh sawal asahaj kar sakta hai.",
    tabdeeli:"Aaj kisi personal sawal se pehle khud se poochiye: 'Kya mujhe waqai is maloomat ki zaroorat hai?'" },
  { id:"forward-se-pehle-tasdeeq", title:"Forward Karne Se Pehle Tasdeeq", tags:["Tahqeeq","Sach","Zimmedari"], ic:"🔍", cat:"digital", color:"#5c7cfa",
    scene:"'Hadith mein likha hai...' 'Doctor ne kaha hai...' 'NASA ne prove kiya...' 'Islam mein yeh haraam hai...' 'Kal se yeh rule lag raha hai...', aur hum bas forward kar dete hain.",
    masla:"Bina tasdeeq kiye koi baat aage badhana ghalat maloomat failane ka sabab ban sakta hai, khaas kar jab baat Deen ya kisi insaan se mutaliq ho.",
    islam:"Qur'an maloomat ki tasdeeq karne ki ahmiyat batata hai, khaas kar jab uske asraat kisi aur par parte hon.",
    nabi:null,
    galti:"Jaldi mein ya 'sawab ki niyyat' se hum bina check kiye hi aisi baatein forward kar dete hain jo ghalat nikalti hain.",
    tabdeeli:"Kisi Islami baat ko 'Hadith' kehne se pehle uska sahi hawala check kijiye." },
  { id:"gaadi-chala-rahe-gussa-nahi", title:"Gaadi Chala Rahe Hain, Gussa Nahi", tags:["Sabr","Driving","Akhlaq"], ic:"🚘", cat:"huqooq", color:"#3f8fe0",
    scene:"Kisi ne overtake kar diya, kisi ne indicator nahi diya, auto suddenly saamne aa gaya, bike beech mein aa gayi, aur hamara mood kharab, horn, abuse, chasing, aggressive driving.",
    masla:"Road par doosron ki galtiyan hamesha hamare control mein nahi, lekin apna reaction control karna hamare haath mein hota hai.",
    islam:"Gussa zabt karna aur sabr se kaam lena har halat mein, chahe road par ho ya ghar mein, Islami akhlaaq ka hissa hai.",
    nabi:null,
    galti:"Hum road par dusron ki chhoti galti ko bhi apni izzat ka sawal bana lete hain, jabke woh sirf ek aam insani ghalti hoti hai.",
    tabdeeli:"Aaj road par koi irritate kare, consciously ek lambi saans lijiye aur khud se kahiye: 'Mujhe apna reaction control karna hai.'" },
  { id:"ghar-bahar-achha-bartao", title:"Ghar Walon Se Achha Bartao Bahar Walon Se Bhi Zaroori Hai", tags:["Akhlaq","Ghar","Rishtey"], ic:"❤️", cat:"ghar", color:"#d6708f",
    scene:"Office mein 'Thank you!', restaurant mein 'Please', friends ke saath 'Bhai jaan!', aur ghar mein 'Chup karo!' Kabhi hum ajnabiyon ko apna best version dikhate hain aur apne ghar walon ko apna worst.",
    masla:"Asal imtihan aksar wahi hota hai jahan hum sabse zyada comfortable hote hain, apne ghar mein.",
    islam:"Ghar walon ke saath husn-e-akhlaq utna hi zaroori hai jitna bahar ke logon ke saath, balki unka haq pehle hai.",
    nabi:null,
    galti:"Hum sochte hain ghar wale toh 'apne' hain, isliye unke saath sakhti chalti hai, jabke yehi soch rishton ko kamzor kar deti hai.",
    tabdeeli:"Aaj ghar mein kisi ek shakhs se wohi narmi dikhaiye jo aap kisi mehmaan ke saath dikhate hain." },
  { id:"gheebat-forwarded-message", title:"Gheebat Ka Naya Naam: 'Forwarded Message'", tags:["Gheebat","Zubaan","Amanat"], ic:"🗣️", cat:"digital", color:"#5c7cfa",
    scene:"Pehle log saamne baith kar kisi ki burai karte the. Aaj hum screenshot bhejte hain, voice note forward karte hain, private photo circulate karte hain, aur phir kehte hain: 'Bas bata raha hoon.'",
    masla:"Agar kisi ki ghair-maujoodgi mein uski aisi baat discuss ho rahi hai jo usay maloom ho toh bura lage, toh yeh gheebat hi hai, chahe medium koi bhi ho.",
    islam:"Gheebat ko Qur'an mein apne mare hue bhai ka gosht khane jaisa bataya gaya hai, yeh ek sakht mana amal hai.",
    nabi:null,
    galti:"Hum isay 'sirf information share karna' samajh kar justify kar dete hain, jabke niyyat aksar burai bayan karna hi hoti hai.",
    tabdeeli:"Koi forward karne se pehle poochiye: 'Kya yeh gheebat toh nahi ban rahi?'" },
  { id:"glass-paani-chhodna", title:"Glass Mein Paani Chhodna Bhi Sochiye", tags:["Israf","Wasail","Zimmedari"], ic:"🥛", cat:"maahol", color:"#4caf7d",
    scene:"Restaurant mein paani manga, do glass piya, aadha glass chhod diya, phir naya le liya.",
    masla:"Paani unlimited lagta hai kyunke nal kholte hi aa jaata hai, lekin resources unlimited nahi hain.",
    islam:"Israf se bachne ka usool sirf khane par nahi, rozana ki har consumption par lagu hota hai.",
    nabi:null,
    galti:"Hum paani ko 'free' resource samajh lete hain, jabke yeh bhi Allah ki ek nemat hai jiska shukr aur hifazat zaroori hai.",
    tabdeeli:"Glass mein utna hi paani lijiye jitna aap pee sakte hain." },
  { id:"gussa-reaction-mat-do", title:"Gussa Aaya Toh Reaction Mat Do", tags:["Sabr","Tahammul","Pachhtawa Se Bachna"], ic:"😤", cat:"akhlaq", color:"#5cb85c",
    scene:"Gussa aana insani hai. Lekin gusse mein message bhejna, dhamki dena, rishta todna, insult karna, social media par post karna, ya kisi ko office mein embarrass karna, yeh sab baad mein pachhtawe ka sabab ban sakta hai.",
    masla:"Gusse mein liya gaya faisla aksar woh nuqsan pahunchata hai jo sahi halat mein hum kabhi na karte.",
    islam:"Ghussa zabt karna aur sabr se kaam lena bohot bada akhlaqi usool hai.",
    nabi:"Nabi ﷺ ne farmaya: taaqatwar woh nahi jo kushti mein jeete, taaqatwar woh hai jo gusse ke waqt apne aap par qabu rakhe.",
    galti:"Hum gusse ko apni 'sacchai' samajh lete hain, jabke woh sirf ek waqti jazbaat hota hai jo guzar jaata hai.",
    tabdeeli:"Jab gussa aaye, turant response dene ke bajaye kuch waqt ka waqfa lijiye, 'Gussa = Pause' ko apna usool banaiye." },
  { id:"har-baat-jawab-nahi", title:"Har Baat Ka Jawab Dena Zaroori Nahi", tags:["Khamoshi","Sabr","Pukhta-Fehmi"], ic:"🔕", cat:"zubaan", color:"#7e6fd6",
    scene:"WhatsApp par kisi ne kuch kaha, Instagram comment mein kisi ne provoke kiya, office mein kisi ne taunt kiya, aur hum turant reply karte hain. Phir woh reply, phir counter-reply, aur 30 minute baad pata chalta hai ke hum apna waqt aur sukoon dono kho chuke hain.",
    masla:"Har baat ka jawab dena zaroori nahi, aur har argument jeetna bhi zaroori nahi.",
    islam:"Fuzool bahason se bachna aur zaban ko qabu mein rakhna Islami akhlaaq ka hissa hai.",
    nabi:"Nabi ﷺ ki taleem mein achhi baat kehna ya khamosh rehna ek bunyadi usool hai (Sahih Bukhari 6475).",
    galti:"Hum sochte hain ke khamosh rehna 'haar maanna' hai, jabke kabhi conversation chhod dena hi asal samajhdari hai.",
    tabdeeli:"Agli baar koi online provoke kare, reply dene se pehle khud se poochiye: 'Kya is bahas se kuch hasil hoga?'" },
  { id:"comparison-zaroori-nahi", title:"Har Cheez Mein Apna Comparison Zaroori Nahi", tags:["Shukr","Qanaat","Sukoon"], ic:"📊", cat:"akhlaq", color:"#5cb85c",
    scene:"Uske paas car hai. Uska ghar bada hai. Uski salary zyada hai. Uski shaadi ho gayi. Uske bachche hain. Uske paas latest phone hai, aur hum apni zindagi ko uski highlight reel se compare karna shuru kar dete hain.",
    masla:"Comparison aksar shukr ko kha jaata hai. Jo kuch Allah ne hamein diya hai, uski qadr comparison ki wajah se dhundli pad jaati hai.",
    islam:"Allah ki taqseem par raazi rehna aur apni nematon ka shukr ada karna Imaan ka hissa hai.",
    nabi:null,
    galti:"Hum jaane-anjaane social media par doosron ki zindagi ke sirf 'best moments' dekh kar apni poori zindagi ko unke saath tolne lagte hain.",
    tabdeeli:"Aaj kisi se comparison ka khayal aaye, toh foran apni teen nematein yaad kijiye." },
  { id:"status-daalna-zaroori-nahi", title:"Har Cheez Status Par Daalna Zaroori Nahi", tags:["Niji Khushi","Riya Se Bachna","Sukoon"], ic:"📵", cat:"digital", color:"#5c7cfa",
    scene:"Khana, trip, new phone, gift, salary, shopping, ghar, relationship, har moment ko public karna zaroori nahi.",
    masla:"Kuch khushiyan sirf aapki aur aapke apno ki bhi ho sakti hain. Har waqt dusron ko dikhane ki chahat kabhi-kabhi asal khushi ko hi kam kar deti hai.",
    islam:"Niyyat ko khalis rakhna aur apni nematon ki numaish se bachna Islami adab ka hissa hai.",
    nabi:null,
    galti:"Hum kisi achhi khabar ke milte hi sabse pehle status lagane ki soch lete hain, bajaye iske ke pehle us lamhe ko khud mehsoos karein.",
    tabdeeli:"Aaj kuch achha ho toh foran status lagane ke bajaye usay kuch der sirf enjoy kijiye." },
  { id:"jism-amanat", title:"Jism Bhi Allah Ki Amanat Hai", tags:["Warzish","Taaqat","Jismani Sargarmi"], ic:"💪", cat:"sehat", color:"#e0893f",
    scene:"Subah se raat tak kursi par baithe kaam kiya, phone dekha, khaana khaya, phir so gaye. Poore din mein jism ne shayad chand kadam hi chale.",
    masla:"Jab jismani harkat zindagi se nikal jaati hai, kamzori aur susti chup-chaap jagah bana leti hai. Hum sehat ko sirf dua ya dawa tak samajh lete hain, jabke jism khud bhi ek amanat hai jiski hifazat hum par farz hai.",
    islam:"Islam mein taaqat aur sehat ko pasandeedah qarar diya gaya hai. Taaqat sirf dikhne ki cheez nahi, balki woh salahiyat hai jisse insan apne Rab ki ibadat behtar tareeqe se kar sake aur apni zimmedariyan behtar nibha sake.",
    nabi:"Nabi ﷺ ne farmaya ke taaqatwar momin, kamzor momin se behtar aur Allah ko zyada mehboob hai, aur sath yeh taleem di ke har momin faida-mand cheez hasil karne ki koshish kare (Sahih Muslim 2664). Nabi ﷺ khud Hazrat Aisha RA ke sath daudne ka musabaqa karte the.",
    galti:"Aksar hum sochte hain 'waqt nahi milta' ya 'kal se shuru karunga', jabke chhoti si rozana koshish bhi is amanat ki hifazat ka zariya ban sakti hai.",
    tabdeeli:"Rozana sirf 15-20 minute ki sair ya koi halki jismani sargarmi apni routine mein shamil kijiye." },
  { id:"kaam-karne-wala-chhota-nahi", title:"Kaam Karne Wale Ko Chhota Mat Samjho", tags:["Mehnat Ki Izzat","Huqooq","Insaniyat"], ic:"👷", cat:"akhlaq", color:"#5cb85c",
    scene:"Driver, cleaner, delivery boy, security guard, domestic worker, office assistant, construction worker, hum unki service use karte hain, lekin kya hum unko izzat bhi dete hain?",
    masla:"Kisi ka profession uski insani qeemat decide nahi karta. Jo kaam chhota lagta hai, uska karne wala chhota nahi hota.",
    islam:"Mazdoor aur khidmatgaar ke huqooq ko Islam mein bohot ahmiyat di gayi hai.",
    nabi:"Nabi ﷺ ki taleemaat mein workers ke huqooq ko seriously liya gaya hai, mazdoor ki ujrat usko uska paseena sukhne se pehle dene ki hidayat mashhoor hai (Ibn Majah 2443).",
    galti:"Hum na chahte hue bhi apni baat mein ek lehja istemal kar lete hain jo kisi 'bade' officer se alag hota hai, yeh farq khud mehsoos karna zaroori hai.",
    tabdeeli:"Aaj kisi aise shakhs ka shukriya ada kijiye jiska kaam aksar nazar-andaz hota hai." },
  { id:"kaam-kal-par-mat-daliye", title:"Kaam Ko Kal Par Mat Daliye", tags:["Zimmedari","Waqt","Stress Se Bachna"], ic:"🗓️", cat:"waqt", color:"#c79a2e",
    scene:"Email baad mein, assignment baad mein, bills baad mein, important call baad mein, document baad mein, phir deadline aa jaati hai aur hum stress mein kaam karte hain.",
    masla:"Har derri laziness nahi hoti, lekin jaan-boojh kar zaroori zimmedari ko baar baar postpone karna ek aadat ban sakta hai jo khud hamare liye takleef-deh hai.",
    islam:"Apni zimmedariyon ko waqt par poora karna amanat ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'kal zyada waqt milega', jabke kal bhi utna hi masroof hota hai jitna aaj.",
    tabdeeli:"Aaj ek aisa kaam chuniye jo aap kai din se postpone kar rahe hain aur sirf 15 minute usi par laga dijiye." },
  { id:"kachra-sirf-kachra-nahi", title:"Kachra Sirf Kachra Nahi", tags:["Ijtimaai Safai","Zimmedari","Imaan"], ic:"🗑️", cat:"maahol", color:"#4caf7d",
    scene:"Aap restaurant se nikle. Cup haath mein tha. Dustbin 5 metre door tha, lekin aapne cup wahin bench par rakh diya aur chal diye.",
    masla:"Yeh chhota sa amal 'sirf ek cup' nahi, is raaste se guzarne wale agle insaan ke liye woh gandagi aur takleef ban jaata hai. Hum safai ko apne ghar ya masjid tak mehdood samajh lete hain, jabke raaste, park, station, sab jagah ki safai bhi hamari zimmedari hai.",
    islam:"Imaan ke darjaat mein se ek yeh bhi hai ke raaste se takleef-deh cheez hata di jaye. Yani apni jagah saaf rakhna kaafi nahi, doosron ke raaste ko mehfooz rakhna bhi deen ka hissa hai.",
    nabi:"Nabi ﷺ ne raaste se takleef-deh cheez hatane ko sadqah aur Imaan ki ek shaakh qarar diya.",
    galti:"Hum sochte hain 'itni si cheez se kya farq padega', lekin yahi soch jab sab log rakhte hain, poora raasta gandagi se bhar jaata hai.",
    tabdeeli:"Jahan bhi guzrein, apne haath ki cheez khud dustbin tak le jaiye, chahe woh chand kadam door hi kyun na ho." },
  { id:"khane-ki-burai-mat-kijiye", title:"Khane Ki Burai Mat Kijiye", tags:["Shukr","Mehnat Ki Qadar","Adab"], ic:"🍲", cat:"khana", color:"#c0563f",
    scene:"'Yeh kya bana diya?' 'Bilkul bekaar hai.' 'Isme taste hi nahi.' Kisi khane ko pasand na karna alag baat hai, lekin use banane wale ki mehnat ko insult karna alag.",
    masla:"Jab hum khane ki burai karte hain, toh sirf khana nahi, us mehnat ko bhi kam-tar kehte hain jo kisi ne hamare liye ki.",
    islam:"Khane ki na-pasandeedgi zahir karne ka tareeqa bhi adab se hona chahiye.",
    nabi:"Nabi ﷺ ke tarz-e-khana mein yeh misaal milti hai ke agar koi khana pasand na aaye toh usay chhod dijiye, uski burai mat kijiye.",
    galti:"Hum kabhi majak mein, kabhi sacchai ke naam par khane ki itni tanqeed kar dete hain ke banane wale ka dil toot jaaye.",
    tabdeeli:"Pasand nahi? Bas politely keh dijiye: 'Mujhe shayad yeh pasand nahi, main kuch aur le leta hoon.'" },
  { id:"paisa-rokna-chhoti-baat-nahi", title:"Kisi Ka Paisa Rokna Chhoti Baat Nahi", tags:["Haq","Zulm","Zimmedari"], ic:"💸", cat:"maal", color:"#b8860b",
    scene:"Salary delay, freelancer ka payment delay, worker ka payment delay, refund rokna, commission rokna, 'kal de denge' kehte rehna.",
    masla:"Agar aapke paas kisi ka haq dene ki salahiyat hai aur phir bhi jaan-boojh kar derri kar rahe hain, toh yeh sirf derri nahi, zyadti hai.",
    islam:"Kisi ka haq rokna, jabke dene ki istita'at ho, Islam mein sakht na-pasandeedah amal hai.",
    nabi:"Nabi ﷺ se riwayat hai ke maldaar shakhs ka qarz ki adaigi mein derri karna zulm hai (Jami' at-Tirmidhi).",
    galti:"Hum sochte hain 'thodi derri se kya farq padega', jabke saamne wale ka ghar ka kharcha usi paise par rukha ho sakta hai.",
    tabdeeli:"Kisi ka payment pending hai toh 'kabhi de denge' ke bajaye exact tareekh tay kijiye." },
  { id:"majboori-tamasha-nahi", title:"Kisi Ki Majboori Ko Tamasha Mat Banao", tags:["Izzat-e-Nafs","Hamdardi","Akhlaq"], ic:"🎭", cat:"akhlaq", color:"#5cb85c",
    scene:"Kisi ke kapde purane hain. Kisi ke paas achha phone nahi. Koi financial problem mein hai. Kisi ki English weak hai. Koi physically slow hai. Kisi ko public mein galti ho gayi.",
    masla:"Kya us waqt phone nikal kar video banana zaroori hai? Kya friends ke group mein uski mazaak banana zaroori hai? Kisi ki kamzori hamare liye tafreeh ka zariya nahi honi chahiye.",
    islam:"Islami akhlaaq ka ek important hissa insaan ki izzat-e-nafs (dignity) ko mehfooz rakhna hai.",
    nabi:null,
    galti:"Hum kabhi mazaak mein, kabhi social media ke liye content ki talaash mein kisi ki majboori ko unknowingly tamasha bana dete hain.",
    tabdeeli:"Aaj kisi ki weakness notice ho toh usay content nahi, insaan samjhiye." },
  { id:"line-mein-haq", title:"Line Mein Apna Haq, Dusron Ka Bhi Haq", tags:["Qataar","Usool","Ijtimaai Nazm-o-Zabt"], ic:"🚦", cat:"huqooq", color:"#3f8fe0",
    scene:"Aap 20 minute se billing counter ki line mein khade hain. Peeche bhi kai log intezar mein hain. Achanak koi 'bas ek minute' kehte hue beech mein ghus jaata hai.",
    masla:"Yeh sirf line todna nahi, us shakhs ne sirf apna waqt nahi bachaya, balki peeche khade har insaan ka waqt aur haq bhi chheen liya.",
    islam:"Jahan bhi hamara haq kisi doosre ke haq se juda ho, wahan adab aur insaaf zaroori hai. Doosron ka haq maarna, chahe woh waqt ka hi haq kyun na ho, Islam mein na-pasandeedah amal hai.",
    nabi:"Nabi ﷺ ne musalmanon ko aapas mein insaaf aur baraabari ki taleem di, aur kisi ke haq mein na-haq dakhal-andaazi se mana farmaya.",
    galti:"Jaldi mein hum khud se keh dete hain 'mera kaam zaroori hai', lekin bhool jaate hain ke line mein khade har shakhs ka kaam bhi usi tarah zaroori hai.",
    tabdeeli:"Apni baari ka sabr se intezar kijiye, line ho ya traffic, apna haq utna hi lijiye jitna aapka hai." },
  { id:"maafi-maangna-chhota-nahi", title:"Maafi Maangne Mein Chhota Kaun Ho Gaya?", tags:["Inkisaar","Sach","Rishte"], ic:"🙏", cat:"akhlaq", color:"#5cb85c",
    scene:"'Galti meri thi' kehna mushkil hai. Hum explanation dete hain: 'Haan, lekin usne pehle...', 'Maine isliye kiya kyunki...', 'Actually meri intention yeh nahi thi...'",
    masla:"Kabhi-kabhi simple 'mujhse galti hui, mujhe maaf kar do' itna hi kaafi hota hai, lekin hum iski jagah safai dene lagte hain.",
    islam:"Apni ghalti tasleem karna kamzori nahi, balki inkisaar aur achhe akhlaaq ki nishani hai.",
    nabi:null,
    galti:"Hum justification ko maafi samajh lete hain, jabke saamne wala sirf itna sunna chahta hai ke hamari ghalti ka ehsaas hai.",
    tabdeeli:"Agar kisi se aapki recent galti hui hai, justification se pehle seedhi maafi dijiye." },
  { id:"masjid-adab", title:"Masjid Mein Sirf Namaz Nahi, Adab Bhi Hai", tags:["Masjid Ka Adab","Sukoon","Ikhlaas"], ic:"🕌", cat:"ibadat", color:"#9b6fd6",
    scene:"Masjid mein jaakar hum namaz padhte hain, lekin kya hum apne rawayye ka bhi khayal rakhte hain? Jootay idhar-udhar rakh dena, saf mein jagah chhod dena, phone loud rakhna, badbu ke saath logon ke darmiyan khade hona, masjid mein kachra chhod dena.",
    masla:"Masjid mein ibadat ke saath doosre musalliyon ke sukoon ka bhi khayal hona chahiye, sirf apni namaz mukammal karna kaafi nahi.",
    islam:"Masjid Allah ka ghar hai, aur wahan aane wale har insaan ka haq hai ke usay sukoon aur adab ka maahol mile.",
    nabi:"Nabi ﷺ ne badbu wali cheez kha kar masjid mein aane ke hawale se doosre logon ko takleef se bachane ki taleem di.",
    galti:"Hum sochte hain 'main toh sirf namaz ke liye aaya hoon', aur in chhoti baaton ko ignore kar dete hain, jabke yahi chhoti baatein doosron ke khushu ko bhi mutasir karti hain.",
    tabdeeli:"Masjid mein jaane se pehle apne kapde, body aur breath ka khayal rakhiye." },
  { id:"mehmaan-phone-side", title:"Mehmaan Aaye Toh Phone Side Mein Rakhiye", tags:["Mehmaan-Nawazi","Tawajjo","Adab"], ic:"📴", cat:"ghar", color:"#d6708f",
    scene:"Guest aaya, hum kehte hain 'Aaiye aaiye!' phir phone khola, WhatsApp, Instagram, reels, messages. Guest saamne baitha hai, lekin tawajjo screen par.",
    masla:"Hospitality sirf khana serve karna nahi, apna waqt dena bhi mehmaan-nawazi ka hissa hai.",
    islam:"Mehmaan ki izzat aur uski taraf poori tawajjo dena Islami adab ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'bas ek message dekh leta hoon', jabke guest ko yeh adhoori tawajjo foran mehsoos ho jaati hai.",
    tabdeeli:"Mehmaan ke saamne phone side mein rakh dijiye jab tak woh ghar mein hai." },
  { id:"mehmaan-ghar-hisab-nahi", title:"Mehmaan Ke Ghar Har Cheez Ka Hisab Mat Lagaiye", tags:["Mehmaan-Nawazi","Qanaat","Izzat"], ic:"🏡", cat:"ghar", color:"#d6708f",
    scene:"'Kitne dishes hain?' 'AC kitna bada hai?' 'Furniture kitne ka hoga?' 'Shaadi mein kitna kharcha hua?', kabhi hum mehmaan bankar jaate hain aur auditor bankar wapas aate hain.",
    masla:"Mehmaan-nawazi ka matlab sirf khana khana nahi, host ki izzat aur uski mehnat ki qadr karna bhi hai.",
    islam:"Mehmaanon ki izzat karna aur unki mehmaan-nawazi ko sahi niyyat se qubool karna Islami adab hai.",
    nabi:null,
    galti:"Hisaab-kitaab lagane ki aadat hamein doosron ki mehnat aur niyyat dekhne se rok deti hai, hum sirf numbers dekhte reh jaate hain.",
    tabdeeli:"Agli dafa kisi ke ghar jaakar cost calculate karne ke bajaye host ki mehnat appreciate kijiye." },
  { id:"muskurana-rawayya", title:"Muskurana Bhi Ek Rawayya Hai", tags:["Sadqah","Achha Lafz","Chhoti Nekiyan"], ic:"🙂", cat:"akhlaq", color:"#5cb85c",
    scene:"Hum aksar sadqah ko sirf paisa dene se jodte hain. Lekin security guard ko salaam, waiter ko thank you, shopkeeper se izzat se baat, buzurg ko smile, pareshaan dost ko do minute dena, yeh sab bhi chhoti chhoti nekiyan hain.",
    masla:"Hum sochte hain ke sadqah sirf tab hota hai jab jeb se kuch nikale, aur in chhoti baaton ko 'bas normal manners' samajh kar inki qadr nahi karte.",
    islam:"Achha lafz, madad aur raaste se takleef-deh cheez hata dena bhi sadqah ke examples mein aaye hain.",
    nabi:"Nabi ﷺ ne farmaya ke muskura kar milna bhi sadqah hai.",
    galti:"Hum badi nekiyon ki talaash mein rehte hain, aur rozana milne wali in chhoti nekiyon ko nazar-andaz kar dete hain.",
    tabdeeli:"Aaj kisi ek shakhs ko, chahe woh ajnabi hi kyun na ho, khushdili se muskura kar salaam kijiye." },
  { id:"office-samaan-apka-nahi", title:"Office Ka Samaan Aapka Nahi", tags:["Amanat","Zimmedari","Diyanat"], ic:"🖇️", cat:"maal", color:"#b8860b",
    scene:"Office ka printer, stationery, fuel, internet, company ka laptop, office supplies, hum aksar sochte hain 'company ka hi toh hai'.",
    masla:"Company ka matlab kisi individual ka nahi hota. Jo resource aapko kaam ke liye diya gaya hai, uska personal misuse trust ka masla ban sakta hai.",
    islam:"Amanat mein wohi cheezein bhi shamil hain jo kaam ke liye aapko saunpi gayi hain, chahe woh kisi company ki hi kyun na hon.",
    nabi:null,
    galti:"Hum isay 'chhoti si baat' samajh lete hain, jabke yeh amanat mein khayanat ka ek roop hai.",
    tabdeeli:"Office ki kisi cheez ko ghar le jaane ya personal use se pehle khud se poochiye: 'Kya mujhe iski ijazat hai?'" },
  { id:"online-zubaan-ka-adab", title:"Online Bhi Zubaan Ka Adab Rakhiye", tags:["Guftugu","Akhlaq","Zimmedari"], ic:"⌨️", cat:"digital", color:"#5c7cfa",
    scene:"Screen ke peeche rehkar hum woh baatein likh dete hain jo saamne wale ko kabhi nahi kehte, comment section mein insult, anonymous account se abuse, group mein kisi ka mazaak.",
    masla:"Aapki zaban badli nahi hai, sirf keyboard ban gaya hai. Online hone se jawabdari khatam nahi ho jaati.",
    islam:"Achhi baat kahna ya khamosh rehna, yeh usool online aur offline dono jagah barabar lagu hota hai.",
    nabi:"Nabi ﷺ ne farmaya: jo Allah aur Qiyamat ke din par imaan rakhta hai, woh achhi baat kahe ya khamosh rahe (Sahih Bukhari 6475).",
    galti:"Hum sochte hain screen ke peeche 'anonymity' hamein zimmedari se azaad kar deti hai, jabke Allah ke nazdeek kuch bhi posheeda nahi.",
    tabdeeli:"Online koi comment likhne se pehle socha kijiye: 'Kya main yeh baat saamne mil kar bhi kehta?'" },
  { id:"paaki-sirf-ibadat-nahi", title:"Paaki Sirf Ibadat Ke Liye Nahi", tags:["Safai","Zaati Safai","Zahiri Hulia"], ic:"🧼", cat:"zaati-safai", color:"#2fb6b0",
    scene:"Namaz ka waqt hua, wuzu kiya, masjid pahunche, lekin subah se poore din kapde wahi the jo kal pehne the, aur baal bhi do din se nahi sanware.",
    masla:"Jab safai sirf namaz ke wuzu tak mehdood ho jaati hai, rozmarra ki zindagi mein badbu ya zaahiri be-tawajjohi dusron ke liye, ghar walon, daftar ke saathiyon, masjid mein saath khade logon ke liye, takleef ka sabab ban sakti hai.",
    islam:"Qur'an mein masjid jaate waqt zeenat yani achhi haalat aur libas ka khayal rakhne ka hukm hai. Yani zahiri paaki sirf ibadat ke waqt ke liye khaas nahi, rozmarra ki zindagi ka hissa honi chahiye.",
    nabi:"Nabi ﷺ ne garlic ya pyaz khane ke baad masjid aane se mana farmaya, kyunke uski badbu doosre namaziyon ko takleef de sakti thi.",
    galti:"Hum sochte hain 'ghar mein hi toh hoon, kaun dekhega', jabke ghar wale bhi utne hi haqdar hain hamari achhi zahiri haalat ke.",
    tabdeeli:"Roz nahana, saaf kapde pehenna aur miswak/brush ka khayal rakhna apni rozana zindagi ka mamool banaiye, sirf namaz ke waqt ka nahi." },
  { id:"padosi-bagal-wala-nahi", title:"Padosi Sirf Bagal Wala Ghar Nahi", tags:["Padosi Ka Haq","Sukoon","Zimmedari"], ic:"🏘️", cat:"huqooq", color:"#3f8fe0",
    scene:"Padosi ko sirf tab yaad karna jab usse koi kaam ho, yeh padosi ka haq nahi. Loud music, aapki gaadi se uska gate block hona, aapka kachra uske saamne, late-night noise, construction ki wajah se unnecessary takleef.",
    masla:"Hamari azaadi kahin na kahin kisi aur ke sukoon ki qeemat par toh nahi aa rahi? Yeh sawal khud se poochna zaroori hai.",
    islam:"Nabi ﷺ ne padosi ko takleef na dene ko Imaan ke saath joda hai, yani padosi ka khayal rakhna sirf achhi aadat nahi, Imaan ka tagaza hai.",
    nabi:"Nabi ﷺ ne baar baar padosi ke huqooq ki taakeed farmayi, is hadd tak ke Sahaba ko guman hone laga ke shayad padosi ko wirasat mein hissedaar bhi bana diya jaayega.",
    galti:"Hum apni azaadi aur convenience ko priority dete hain, aur bhool jaate hain ke iska asar bagal wale ghar tak pahunchta hai.",
    tabdeeli:"Aaj ek aisi cheez identify kijiye jo aapki wajah se padosi ko inconvenience de sakti hai, aur usay kam kijiye." },
  { id:"parking-ka-haq", title:"Parking Ka Bhi Haq Hai", tags:["Huqooq","Zimmedari","Ijtimaai Nazm"], ic:"🅿️", cat:"huqooq", color:"#3f8fe0",
    scene:"Gaadi park ki, do parking spaces occupy kar li, kisi ke gate ke saamne park kar diya, emergency exit block kar diya, 'bas 10 minute ke liye hai.'",
    masla:"Jis insaan ka gate block hua, uske liye woh 10 minute bohot important ho sakte hain. Apni convenience ko doosron ki inconvenience mat banaiye.",
    islam:"Doosron ke raaste aur haq mein rukawat daalna Islam mein na-pasandeedah amal hai.",
    nabi:null,
    galti:"Hum sochte hain 'thodi der ki baat hai, koi nahi aayega', jabke wahi 'thodi der' kisi ke liye badi museebat ban sakti hai.",
    tabdeeli:"Gaadi park karte waqt sochiye: 'Kya yahan kisi aur ka raasta toh nahi ruk raha?'" },
  { id:"pet-bharna-zindagi-bharna", title:"Pet Bharna Aur Zindagi Bharna Alag Hai", tags:["Zyada Khana","Mota-pan","Tarz-e-Zindagi"], ic:"⚖️", cat:"sehat", color:"#e0893f",
    scene:"Kisi ka jism dekh kar humne mazaak mein keh diya 'kitna khaata hai yeh', bina yeh jaane ke uski wajah kya hai.",
    masla:"Kisi shakhs ki jismani banawat apne aap mein gunah nahi. Medical conditions, genetics, umar, dawaiyan, hamal, in sab ka asar jism par parta hai. Masla tab hai jab hum kisi ke jism ko dekh kar uske kirdaar ka faisla sunane lagte hain.",
    islam:"Qur'an ka usool saaf hai: khao aur piyo, magar israf na karo (7:31). Islam ne khana mana nahi kiya, lekin har waqt pet bhar kar rakhna lifestyle nahi banana chahiye, aur kisi ke zahiri jism par taana kasna bhi Islami adab ke khilaf hai.",
    nabi:"Nabi ﷺ ne khane mein miyaanaroi ki taleem di, zarurat ke mutabiq khana, aur zyada zarurat ho to pet ko teen hisson mein taqseem karna (Tirmidhi 2380, Hasan Sahih).",
    galti:"Hum na chahte hue bhi kisi ke jism par comment kar dete hain, yeh soch kar ke yeh 'bas ek mazaak' hai, jabke woh shakhs ke liye takleef-deh ho sakta hai.",
    tabdeeli:"Kisi ke jism par comment karne se pehle ruk jaiye, khud apni khurak mein miyaanaroi apnaiye, aur doosron ke jism ko un ke aur Allah ke darmiyan rehne dijiye." },
  { id:"pet-godaam-mat-banao", title:"Pet Ko Godaam Mat Banao", tags:["Khana-Peena","Miqdar Ka Khayal","Aitedaal"], ic:"🍽️", cat:"khana", color:"#c0563f",
    scene:"Buffet mein plate bhar li, dal, chawal, salad, mithai, sab ek saath, sirf isliye kyunke 'paise diye hain toh sab taste karna hai'.",
    masla:"Pet ko hum ek aisa godaam samajhne lagte hain jise har waqt bharna zaroori hai. Zarurat se zyada lena, phir aadha chhod dena, yeh khane ki be-qadri bhi hai aur sehat ka nuqsan bhi.",
    islam:"Qur'an ka hukm wazeh hai: khao aur piyo, magar israf na karo (7:31).",
    nabi:"Nabi ﷺ ne pet bharne ke bajaye zarurat ke mutabiq khane ki taleem di, aur agar zyada khana zaroori ho jaye, to pet ko teen hisson mein taqseem kiya jaye: ek khane ke liye, ek pani ke liye, ek saans ke liye (Tirmidhi 2380, Hasan Sahih).",
    galti:"Boriyat mein khana, ya 'paisa vasool' karne ki soch mein zarurat se zyada lena, yeh aadatan ho jaata hai, hum isay masla samajhte hi nahi.",
    tabdeeli:"Plate mein utna hi lijiye jitni zarurat ho, baqi baad mein bhi liya ja sakta hai." },
  { id:"phone-samne-insaan", title:"Phone Haath Mein Hai, Lekin Saamne Insaan Hai", tags:["Tawajjo","Rishte","Waqt"], ic:"📱", cat:"digital", color:"#5c7cfa",
    scene:"Friend ke saath baithe hain, phone haath mein. Ammi baat kar rahi hain, phone haath mein. Spouse kuch share kar raha hai, phone haath mein. Bachcha kuch dikhana chahta hai, phone haath mein.",
    masla:"Saamne baitha insaan humse hamari poori tawajjo ka haqdar hai, lekin screen hamesha beech mein aa jaati hai.",
    islam:"Doosron ko apna waqt aur tawajjo dena bhi unke huqooq mein shamil hai.",
    nabi:null,
    galti:"Hum sochte hain 'main sun toh raha hoon', jabke adhoori tawajjo bhi saamne wale ko mehsoos ho jaati hai.",
    tabdeeli:"Aaj kam se kam ek important baat-cheet mein phone side mein rakh kar poori tawajjo saamne wale ko dijiye." },
  { id:"plate-utna-hi-lijiye", title:"Plate Mein Utna Hi Lijiye Jitna Kha Sakte Hain", tags:["Israf","Khana","Aitedaal"], ic:"🍛", cat:"khana", color:"#c0563f",
    scene:"Buffet ho, shaadi ho, hotel ho ya ghar ka dinner, plate bhar li, phir aadha chhod diya.",
    masla:"Khane ki har waste hui miqdar kahin na kahin israf hai, aur israf se bachna Islam ki taleem hai.",
    islam:"Qur'an mein khane-peene ke saath israf se bachne ki saaf hidayat aati hai (7:31), khana allowed hai, enjoy karna allowed hai, lekin zaya karna nahi.",
    nabi:null,
    galti:"Hum sochte hain 'paise diye hain toh zyada lena chahiye', jabke zyada lekar chhod dena asal mein nuqsan hi hai.",
    tabdeeli:"Pehli serving chhoti rakhiye. Zarurat ho toh dobara le lijiye." },
  { id:"public-jagah-property-nahi", title:"Public Jagah Aapki Private Property Nahi", tags:["Public Space","Zimmedari","Ijtimaai Haq"], ic:"🪑", cat:"maahol", color:"#4caf7d",
    scene:"Park mein bench mili, us par kachra chhod diya. Railway station mein bottle rakh di. Lift mein wrapper chhod diya. Washroom use kiya aur agle insaan ke liye use ganda chhod diya.",
    masla:"Public jagah ka matlab yeh nahi ke 'kisi ka nahi'. Public jagah ka matlab hai: sab ka. Aur jo cheez sab ki ho, uske saath zimmedari bhi sab ki hoti hai.",
    islam:"Doosron ke haq ka khayal rakhna aur ijtimaai jaghon ko saaf rakhna Islami akhlaaq ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'yahan koi cleaner hoga, saaf kar dega', aur apni zimmedari kisi aur par daal dete hain.",
    tabdeeli:"Jahan bhi aap ja rahe hain, koshish kijiye ke aapke jaane ke baad jagah pehle se zyada gandi na ho." },
  { id:"public-paisa-amanat", title:"Public Paisa = Amanat", tags:["Shehri Zimmedari","Amanat","Huqooq"], ic:"🏛️", cat:"maal", color:"#b8860b",
    scene:"Government office, public hospital, road, school, railway, public electricity, public property, aksar hum public cheez ko 'free' samajhte hain.",
    masla:"Public resource ka misuse kisi na kisi level par doosron ke haq ko affect karta hai, kyunke yeh sab ki saanjhi amanat hai.",
    islam:"Amanat aur doosron ke huqooq ka khayal rakhna sirf niji maamlaat tak mehdood nahi, ijtimaai zimmedari bhi isi ka hissa hai.",
    nabi:null,
    galti:"Hum sochte hain 'yeh toh sarkar ki cheez hai, mera kya lena-dena', jabke yeh asal mein sab logon ka saanjha haq hai.",
    tabdeeli:"Public property ko apne ghar ki cheez ki tarah mehfooz rakhiye." },
  { id:"rasta-dustbin-nahi", title:"Rasta Aapka Dustbin Nahi", tags:["Safai","Wrapper","Zimmedari"], ic:"🧃", cat:"maahol", color:"#4caf7d",
    scene:"Chips ka packet khaya, wrapper haath mein tha aur aas-paas dustbin nahi mila, toh humne bas use road ke kinare chhod diya. Kabhi gaadi se tissue, bottle ya packet bahar phenk diya.",
    masla:"Hum aksar sochte hain 'ek chhota sa wrapper hi toh hai'. Lekin sawal yeh hai: agar har shakhs ek-ek wrapper chhod de toh pura raasta kachray se bhar jaayega.",
    islam:"Islam mein raaste se takleef-deh cheez hata dena bhi sadqah ke taur par zikr hua hai (Sunnah).",
    nabi:null,
    galti:"'Bas ek wrapper hai' keh kar hum apni responsibility ko chhota kar lete hain, jabke yahi soch sab ki ho jaaye toh masla bada ban jaata hai.",
    tabdeeli:"Apna wrapper dustbin milne tak haath mein rakhiye." },
  { id:"raste-mein-takleef-mat-banaiye", title:"Raste Mein Takleef Mat Banaiye", tags:["Safai","Sadqah","Zimmedari"], ic:"🪨", cat:"maahol", color:"#4caf7d",
    scene:"Raaste mein stone, broken glass, plastic, construction material, bike galat jagah, ya car aise park ki hui ke logon ko road par aana pade.",
    masla:"Kabhi hum takleef create karte hain, kabhi usay remove kar sakte hain, lekin aksar hum dono mein se kuch nahi karte.",
    islam:"Raaste se takleef-deh cheez hata dena sadqah ke mash'hoor examples mein shaamil hai.",
    nabi:"Nabi ﷺ ne is amal ko Imaan ki ek shaakh bhi qarar diya.",
    galti:"Hum sochte hain 'yeh mera kaam nahi', jabke chhoti si koshish kisi aur ke liye bohot bada aaram ban sakti hai.",
    tabdeeli:"Jahan mumkin ho, raaste ki takleef kam kijiye, badhaiye mat." },
  { id:"road-par-akelay-nahi", title:"Road Par Aap Akelay Nahi Hain", tags:["Traffic","Huqooq","Zimmedari"], ic:"🚗", cat:"huqooq", color:"#3f8fe0",
    scene:"Road par sabko jaldi hai, lekin unnecessary horn, wrong-side driving, aggressive overtaking, red light todna, pedestrian ko space na dena, ambulance ko block karna.",
    masla:"Yeh sab sirf traffic violations nahi, doosron ki safety aur haq ka maamla bhi hai.",
    islam:"Doosron ki jaan aur haq ki hifazat karna Islami zimmedari ka ahem hissa hai.",
    nabi:null,
    galti:"Hum apni jaldi ko sabse zyada zaroori samajh lete hain, aur bhool jaate hain ke road par har insaan ki jaan utni hi qeemti hai.",
    tabdeeli:"Aaj driving mein ek cheez consciously practice kijiye: 'Mujhe sirf apni manzil nahi, doosron ki safety bhi dekhni hai.'" },
  { id:"screenshot-amanat", title:"Screenshot Bhi Amanat Hai", tags:["Amanat","Trust","Privacy"], ic:"📸", cat:"digital", color:"#5c7cfa",
    scene:"Kisi ne personal message bheja. Humne screenshot liya, phir friend ko bheja, phir doosre group mein chala gaya, original bhejne wale ko pata bhi nahi.",
    masla:"Digital duniya mein privacy ka concept khatam nahi hua, bas uska medium badal gaya hai. Kisi ne jo baat aapse privately share ki, usay bina permission circulate karna trust ko tod sakta hai.",
    islam:"Amanat sirf paisa ya cheez nahi, kisi ki baat aur raaz bhi amanat hai jiski hifazat zaroori hai.",
    nabi:null,
    galti:"Hum sochte hain 'bas ek close friend ko bheja hai', lekin yahi soch sab ki ho toh baat dheere dheere sab tak pahunch jaati hai.",
    tabdeeli:"Kisi private chat ka screenshot forward karne se pehle permission lijiye." },
  { id:"udhar-yaad-rakhiye", title:"Udhar Liya Hai Toh Yaad Rakhiye", tags:["Qarz","Amanat","Haq"], ic:"📝", cat:"maal", color:"#b8860b",
    scene:"'Bhai, ₹500 kal de dunga.' Phir kal. Phir next week. Phir: 'Yaar yaad hi nahi raha.'",
    masla:"Jis shakhs ne aap par trust karke paisa diya, uska haq aapki memory par depend nahi karna chahiye.",
    islam:"Qur'an qarz ko formally likh kar rakhne tak ki hidayat deta hai, taake kisi ka haq zaya na ho.",
    nabi:null,
    galti:"Hum qarz ko chhoti baat samajh lete hain, jabke saamne wale ke liye woh paisa zaroori ho sakta hai.",
    tabdeeli:"Jo bhi udhar hai, ek simple list bana lijiye: kis se, kitna, kab dena hai." },
  { id:"waiter-bhi-insaan", title:"Waiter Bhi Insaan Hai", tags:["Izzat","Sabr","Service"], ic:"🧑‍🍳", cat:"akhlaq", color:"#5cb85c",
    scene:"Restaurant mein khana order kiya. Kabhi waiter late ho gaya, kabhi order galat aa gaya, kabhi service slow hai, aur hum foran keh dete hain: 'Tum logon ko kaam hi nahi aata!'",
    masla:"Service lene ka matlab yeh nahi ke kisi insaan ko neecha dikhane ka haq mil jaata hai. Galti hui hai toh complaint kijiye, lekin izzat ke saath.",
    islam:"Doosron se baat karte waqt narmi aur izzat ka khayal rakhna Islami adab hai, chahe rishta kaisa bhi ho.",
    nabi:null,
    galti:"Jaldi ya gusse mein hum aise alfaaz bol dete hain jo normal halat mein kabhi nahi bolte, aur bhool jaate hain ke saamne bhi ek insaan hi hai.",
    tabdeeli:"Agli baar service worker se baat karte waqt uska naam lekar ya 'bhai/bhaiya' kehkar respect se baat kijiye." },
  { id:"wuzu-paani-amanat", title:"Wuzu Ka Paani Bhi Amanat Hai", tags:["Israf","Paani","Zimmedari"], ic:"🚿", cat:"maahol", color:"#4caf7d",
    scene:"Wuzu karte waqt nal poora khol diya aur paani behta raha, humne shayad kabhi socha hi nahi ke ibadat ke liye istemal hone wali cheez bhi zaya ki ja sakti hai.",
    masla:"Paaki zaroori hai, lekin paaki ke naam par israf nahi. Nal khula chhodna, zaroorat se zyada shower chalate rehna, brush karte waqt paani behne dena, yeh sab rozana ki aadatein hain jahan hum zimmedari dikha sakte hain.",
    islam:"Islam mein paani ke israf se mana kiya gaya hai, chahe woh ibadat jaisi amal ke liye hi kyun na istemal ho raha ho.",
    nabi:"Nabi ﷺ ne wuzu mein bhi israf se mana farmaya tha, yahan tak ke behte hue dariya ke kinare wuzu karne wale ko bhi paani zaya na karne ki hidayat di gayi hai.",
    galti:"Hum paani ko 'unlimited' samajh lete hain kyunke nal kholte hi aa jaata hai, jabke yeh bhi ek nemat hai jiska hisaab hoga.",
    tabdeeli:"Wuzu mein nal ko zarurat ke mutabiq kholiye, aur kaam ke darmiyan band rakhiye." },
  { id:"doosre-ki-screen", title:"Doosre Ki Screen, Aapka Maamla Nahi", tags:["Privacy","Public Places","Adab"], ic:"👀", cat:"zubaan", color:"#7e6fd6",
    scene:"Bus, auto, metro ya train mein baithe hain. Bagal wala phone use kar raha hai, WhatsApp khula hai, kisi se personal chat ho rahi hai. Humari nazar achanak uski screen par padti hai, aur kabhi jaan-boojhkar thodi gardan ghuma kar dekhte hain: kis se baat kar raha hai, kya likh raha hai, kitne paise ka transaction hai.",
    masla:"Har woh cheez jo aapki aankhon ke saamne aa jaye, uska dekhna jaiz ya munasib nahi ho jaata. Kisi ki screen uski niji jagah hai. Woh public transport mein baitha hai, lekin iska matlab yeh nahi ke uski private guftugu public ho gayi.",
    islam:"Qur'an (49:12) mein tajassus se, yani dusron ke niji maamlaat ko be-wajah khodne se, mana kiya gaya hai. Jo cheez aapke liye nahi hai, usmein jhaankna zaroori nahi.",
    nabi:"Nabi ﷺ se doosre ke ghar mein bila ijazat jhaankne ke bare mein sakht warning milti hai (Sahih Muslim). Aaj ghar ki khidki ki jagah kabhi-kabhi mobile screen humare saamne hoti hai, lekin usool wahi rehta hai.",
    galti:"Hum kehte hain 'bas nazar pad gayi thi', lekin kabhi-kabhi pehli nazar accidental hoti hai, doosri nazar hamari apni choice hoti hai.",
    tabdeeli:"Agli baar public transport mein bagal wale ki screen nazar aaye toh nazar hata lijiye, apna phone dekhiye, bahar dekhiye, zikr kijiye ya bas khamoshi se safar kijiye." },
  { id:"aapki-awaaz-sirf-aapki-nahi", title:"Aapki Awaaz Sirf Aapki Nahi", tags:["Public Places","Noise","Consideration"], ic:"🔊", cat:"huqooq", color:"#3f8fe0",
    scene:"Train mein video chal raha hai, bus mein reel full volume par, metro mein speaker par call, waiting room mein video chal raha hai, aur hum sochte hain 'mujhe toh problem nahi ho rahi'.",
    masla:"Public jagah mein hamari choice ka asar doosron par bhi parta hai. Hamein video sunna hai, lekin doosron ko bhi woh sunna pade, yeh zaroori nahi, shayad koi padh raha ho, koi so raha ho, koi Qur'an padh raha ho, koi sirf khamoshi chahta ho.",
    islam:"Doosron ko takleef na dena aur logon ke sukoon ka khayal rakhna Islami adab ka ahem hissa hai.",
    nabi:"Nabi ﷺ ne padosi ko takleef na dene ke bare mein sakht taakeed farmayi, isi usool ko public jaghon mein bhi laaga jaa sakta hai.",
    galti:"Hum apni convenience ko default samajh lete hain, 'mujhe toh awaaz theek lag rahi hai', jabke sawal yeh hona chahiye ke kya doosron ko bhi theek lag rahi hai.",
    tabdeeli:"Bus, train, metro, waiting room, hospital ya kisi public jagah mein audio ke liye earphones istemal kijiye, aur agar available na hon toh video baad ke liye rakh dijiye." },
  { id:"jahan-khaya-wahan-sameta", title:"Jahan Khaya, Wahan Sameta Bhi", tags:["Safai","Zimmedari","Dining"], ic:"🪣", cat:"maahol", color:"#4caf7d",
    scene:"Restaurant mein khana khaya. Table par cup hai, plate hai, tissue hai, bottle hai, aur hum uth kar seedha chale gaye, yeh soch kar 'staff hai na, woh kar lenge'.",
    masla:"Restaurant staff ka kaam table clear karna ho sakta hai, lekin har woh kaam jo koi doosra kar sakta hai, zaroori nahi ke hum usse karwayein. Agar cup aur plate humare haath se table tak gaya hai, toh apni jagah ko be-wajah messy na chhodna bhi ek consideration hai.",
    islam:"Khane ki qadr karna, israf se bachna aur doosron ka khayal rakhna Islami usool hain. Yeh koi specific hukm nahi ke 'plate khud sink tak le jao', lekin inhi usoolon ko yahan laaga ja sakta hai.",
    nabi:"Sahih Muslim mein Nabi ﷺ ke bartan saaf karne aur khane mein barkat ke hawale se riwayat milti hai, jo khane ki qadr karne ki taraf ishara karti hai.",
    galti:"Hum kabhi service worker ko insaan se zyada 'service' samajhne lagte hain, 'maine paise diye hain, woh karenge'. Paise dene ka matlab yeh nahi ke doosre insaan ki mehnat ki qadr khatam ho gayi.",
    tabdeeli:"Restaurant, office pantry, canteen ya kisi shared dining jagah mein jo cheez aap khud reasonably samet sakte hain, use wahin chhod kar mat jaiye, tissue dustbin mein, bottle designated jagah par, aur table ko be-wajah messy na chhodein." },
  { id:"apna-kaam-khud-saleeqa", title:"Apna Kaam Khud Karna Bhi Saleeqa Hai", tags:["Khud-Inhisaari","Ghar","Zimmedari"], ic:"🧦", cat:"ghar", color:"#d6708f",
    scene:"Ghar mein kuch chahiye toh 'Ammi, le aaiye'. Kapde: 'kisi ko de do'. Paani: 'mere liye bhi le aao'. Apna cup, apni plate, 'koi utha dega', 'Ammi kar lengi'. Kabhi hum ghar mein aise behave karte hain jaise ghar ke doosre log hamari personal khidmat ke liye hain.",
    masla:"Ghar ke kaam sirf kisi ek jins ke 'kaam' nahi hone chahiye. Apne kapde manage karna, apni plate-cup rakhna, apna room saaf rakhna, apna bed banana, yeh khud-inhisaari aur zimmedari hai, kisi ek par bojh nahi.",
    islam:"Ghar mein rehne wala har shakhs ghar ki zimmedari mein apna hissa daale, yeh soch ke 'sirf aurat ka kaam hai' ya 'sirf mard ka kaam hai' Islami taleem ki rooh se mail nahi khaati.",
    nabi:"Hazrat Aisha RA se Sahih al-Bukhari mein riwayat hai ke Nabi ﷺ jab ghar mein hote toh apne ghar ke kaam mein hissa lete, aur jab azaan sunte toh namaz ke liye nikal jaate (Bukhari 5363).",
    galti:"Hum bahar daftar mein poori tarah independent hote hain, apna kaam khud karte hain, apne boss ke saamne zimmedar hote hain, lekin ghar aate hi 'Ammi kar dengi' ya 'Biwi kar degi' keh dete hain. Ghar wale hamare khidmatgaar nahi.",
    tabdeeli:"Aaj se ek simple usool banaiye: 'jo kaam main khud kar sakta/sakti hoon, uske liye kisi aur ko automatically mat bulaiye.' Apni plate uthaiye, apna cup rakhiye, apne kapde khud manage kijiye, aur ghar ke doosre kaamon mein bhi khushi se haath bataiye." },
  { id:"bas-10-minute-matlab-10", title:"“Bas 10 Minute” Ka Matlab 10 Minute Hi Ho", tags:["Waqt Ki Pabandi","Waada","Zimmedari"], ic:"🕰️", cat:"waqt", color:"#c79a2e",
    scene:"Hum kehte hain 'bas 10 minute mein aa raha hoon'. Saamne wala wait karta hai. 10 minute guzarte hain, phir 15, phir 20, phir 30, aur message aata hai 'bas 5 minute aur'. Kabhi hum jaan-boojhkar jhoot nahi bolte, bas apne waqt ka andaza galat laga lete hain.",
    masla:"Agar pahunchne mein realistically 30 minute lagenge, toh 10 minute kehna saamne wale ke waqt ko disturb karta hai. Woh shayad aapka intezar kar raha hai, apna koi kaam rok kar baitha hai, ya kisi appointment ko aapke hisaab se plan kar raha hai. Aapke liye sirf 20 minute ka farq hai, uske liye woh 20 minute bhi uski zindagi ka waqt hai.",
    islam:"Islam waqt ki qadr, ahd aur waade ki pabandi, aur logon ke huqooq ko sanjeedgi se leta hai. Jab kisi ko apne pahunchne ka waqt batayein, toh usay sirf casual andaza na samjhiye, jitna realistically waqt lagega, utna hi batane ki koshish kijiye.",
    nabi:null,
    galti:"Hum sochte hain '10 minute bol deta hoon, raste mein dekh lenge', phir traffic aa jaata hai, parking nahi milti, koi kaam aur aa jaata hai, aur 10 minute kab 30 ban jaate hain pata hi nahi chalta. Masla sirf late hona nahi, masla unrealistic waada karna hai.",
    tabdeeli:"Aaj se jab koi pooche 'kitni der mein aaoge', toh apni best-case timing nahi, realistic timing bataiye, jaise 'takriban 30 minute, traffic par depend karega'. Thoda zyada waqt batana behtar hai, baar baar 'bas 5 minute' kehkar kisi ko wait karwana nahi." },

  { id:"khane-ke-aadaab", title:"Khane Ke Aadaab", tags:["Khane Ka Saleeqa","Sunnah","Shukr"], ic:"🍽️", cat:"khana", color:"#c0563f", guide:true,
    intro:"Khana sirf bhook mitane ka zariya nahi, Allah ki ek nemat hai. Isliye khane ka bhi apna saleeqa hai: khane se pehle Allah ko yaad karna, saaf-suthra rehna, dahine haath se khana, apne saamne se khana, israf se bachna, doosron ka khayal rakhna aur Allah ka shukr ada karna.",
    sections:[
      { heading:"Khane Se Pehle", ic:"🌿", items:[
        "Khana khane se pehle dono haath achhi tarah dhoyein aur safai ka khayal rakhein.",
        "Munh ki safai aur kulla ka bhi khayal rakhein, khaas taur par jab munh mein badbu ho.",
        "Khana shuru karne se pehle Bismillah padhein.",
        "Khane ke liye masnoon dua yaad ho toh padh sakte hain.",
        "Dahine haath se khayein. Nabi ﷺ ne khane ke waqt Allah ka naam lene aur dahine haath se khane ki hidayat di.",
        "Saleeqe, sukoon aur haya ke saath baith kar khayein.",
        "Khana khate waqt apni posture aur libaas ka bhi khayal rakhein.",
        "Khana Allah ki nemat samajh kar shukr ke ehsaas ke saath shuru karein."
      ] },
      { heading:"Khana Kaise Khayein", ic:"🍛", items:[
        "Dahine haath se khayein.",
        "Shared dish ho toh apne saamne se khayein. Doosron ke saamne haath na le jayein.",
        "Jab khana haath se khana munasib ho, toh teen ungliyon se khana Sunnah mein milta hai: angutha, shahadat ki ungli aur beech wali ungli.",
        "Khane ko na bahut jaldi aur na be-wajah bahut dheere khayein. Sukoon aur saleeqe se khayein.",
        "Luqma chhota aur manageable rakhein.",
        "Munh mein luqma ho toh baat karne se bachein.",
        "Munh bhar kar baat na karein.",
        "Khate waqt aise na khayein ke saamne wale ko ghin ya takleef ho.",
        "Ungliyon aur haath ko khane ke darmiyan jitna mumkin ho saaf rakhein.",
        "Shared food ko idhar-udhar na karein aur apni pasand ki cheez dhoondhne ke liye poora bartan na ulat-pulat karein.",
        "Doosron ke liye bhi khana chhodein; sirf apni pasand ki cheezein jama na karein.",
        "Saath baith kar khane walon ka khayal rakhein.",
        "Kisi ke portion ya luqme par nazar na rakhein aur na hi uski plate ko bina zarurat touch karein."
      ] },
      { heading:"Khane Ke Saath Dil Ka Rawayya", ic:"🤲", items:[
        "Khana Allah ki nemat samajh kar khayein.",
        "Khate waqt Allah ka shukr yaad rakhein.",
        "Khane ko dekh kar un logon ko bhi yaad karein jo is waqt bhook ya tangdasti ka saamna kar rahe hain.",
        "Allah se dua karein ke woh zaruratmandon ke liye aasani paida farmaye.",
        "Khana milne par na-shukri aur shikayat ke bajaye shukr ka rawayya rakhein.",
        "Kisi khane ko pasand na aaye toh uski burai na karein. Nabi ﷺ kisi khane ko pasand na karte toh use chhod dete, lekin uski burai nahi karte the.",
        "Khana pasand aaye toh khana banane wale ki tareef aur shukriya karein.",
        "Khana banane wale ki mehnat ko halka na samjhein."
      ] },
      { heading:"Khane Mein Aitidaal", ic:"🍽️", items:[
        "Zyada na khayein.",
        "Pet ko har waqt bhar kar rakhna zaroori nahi.",
        "Nabi ﷺ ne khane mein aitidaal ki taleem di aur ek hissa khane, ek hissa peene aur ek hissa saans ke liye rakhne ka zikr farmaya.",
        "Khane ko 'paisa vasool' karne ke liye zarurat se zyada na khayein.",
        "Buffet mein har cheez plate mein bhar lene ke bajaye jitna kha sakte hain utna hi lein.",
        "Pehle kam lein; zarurat ho toh dobara le sakte hain.",
        "Plate mein khana chhod kar waste na karein.",
        "Qur'an ke mutabiq khaaiye aur peejiye, lekin israf na kijiye."
      ] },
      { heading:"Saath Khane Ke Aadaab", ic:"🤝", items:[
        "Mil baith kar khana mohabbat aur apnapan badhata hai.",
        "Shared dish mein apne saamne se khayein.",
        "Saamne wale ka bhi khayal rakhein.",
        "Achhi cheez sirf apne liye na kheench lein.",
        "Doosre ke portion ko kam na karein.",
        "Kisi ke luqme, plate ya khane ko bina ijazat na chhuyein.",
        "Bachchon aur buzurgon ka bhi khayal rakhein.",
        "Khate waqt doosron ko embarrass na karein.",
        "Kisi ke khane ki quantity, tareeqa ya speed ka mazaak na banayein.",
        "Dastarkhwan ko be-wajah gossip, gheebat aur behas ki jagah na banayein."
      ] },
      { heading:"Luqma Gir Jaaye Toh", ic:"🫓", items:[
        "Agar khane ka luqma gir jaaye aur us par lagi gandagi ko saaf karna mumkin ho, toh use saaf karke khaya ja sakta hai.",
        "Nabi ﷺ ne giray hue luqme ko uthakar uski gandagi door karne aur khane ki taleem di.",
        "Dastarkhwan par gira hua luqma agar saaf ho sakta hai toh use bekaar na samjhein.",
        "Agar luqma aisi jagah gira ho jahan use hygienically saaf karna mumkin na ho, toh sehat aur safai ka khayal rakhein.",
        "Har giray hue luqme ko bina soche uthana maqsad nahi; Sunnah ke saath safai aur sehat ka bhi khayal rakhein."
      ] },
      { heading:"Khane Ke Baad Haath Aur Plate", ic:"👅", items:[
        "Khana khane ke baad plate mein bache hue saaf khane ko be-wajah na chhodein.",
        "Apne bartan ko jitna mumkin ho saaf karke khayein, khane ko waste na karein.",
        "Nabi ﷺ se ungliyon aur bartan ko saaf karne ka zikr milta hai, kyunke barkat khane ke kis hisse mein ho, yeh maloom nahi.",
        "Haath se khaya ho toh ungliyon ko chaatna Sunnah mein milta hai.",
        "Iske baad haath achhi tarah saaf kar lein.",
        "Agar spoon ya cutlery use ki ho toh use bhi saleeqe se rakhein.",
        "Khane ke baad munh ki safai aur kulla karein.",
        "Zarurat ho toh daanton ki safai bhi karein."
      ] },
      { heading:"Agar Aap Mehmaan Hain", ic:"🧑‍🍳", items:[
        "Mezban ne jo khana pesh kiya hai, uski qadr karein.",
        "Khane ki kami, miqdar, zaiqa ya intezam par be-wajah tabsira na karein.",
        "Jitna khana hai utna hi lein.",
        "Sirf apni pasand ki cheez zyada na lein.",
        "Khane ke liye baar baar mana karne ke baad bhi zid na karein.",
        "Mezban ki mehmaan-nawazi ko qadr ki nazar se dekhein.",
        "Khane ke baad Allah se mezban ke liye dua karein.",
        "Uthne se pehle munasib taur par ijazat lein."
      ] },
      { heading:"Agar Aap Mezban Hain", ic:"🏡", items:[
        "Mehmaan ko ikhlas ke saath khana pesh karein.",
        "Khane ke liye peshkash karein, lekin baar baar zid karke mehmaan ko asahaj na karein.",
        "Mehmaan ki zarurat aur aaram ka khayal rakhein.",
        "Sirf isliye zyada khana na khilayein ke 'mana karna badtameezi hai'.",
        "Mehmaan ko izzat aur sukoon dein.",
        "Dawat ko apni haisiyat se bahar jaakar takalluf ka muqabala na banayein."
      ] },
      { heading:"Khane Ke Baad", ic:"🙏", items:[
        "Allah ka shukr ada karein.",
        "Khane ke baad ki masnoon dua padhein.",
        "Dawat mein khaya ho toh mezban ke liye masnoon dua karein.",
        "Haath dobara dhoyein.",
        "Kulla karein aur munh ki safai ka khayal rakhein.",
        "Apni plate/cup ko be-wajah wahin na chhodein.",
        "Agar aap kisi restaurant, office ya shared dining jagah mein hain, toh jo cheez aap khud safely aur aasani se samet sakte hain, use wahin chhod kar na jayein.",
        "Mehmaan hon toh shukriya ada karein aur ijazat lekar uthein."
      ] },
    ],
    closing:"Khana sirf bhook mitana nahi hai. Ek Muslim ke liye khane mein bhi Bismillah hai, shukr hai, safai hai, Sunnah hai, aitidaal hai, doosron ka khayal hai, aur Allah ki nemat ki qadr hai. Khana khaiye, nemat ki qadr kijiye, israf se bachiye aur saleeqe ke saath khaiye." },

  { id:"sone-ke-aadaab", title:"Sone Ke Aadaab", tags:["Neend Ka Saleeqa","Sunnah","Zikr-o-Dua"], ic:"🌙", cat:"neend", color:"#3a4d8f", guide:true,
    intro:"Neend sirf thakawat door karne ka naam nahi, yeh Allah ki ek badi nemat hai. Hum har raat apne din ko khatam karte hain aur phir Allah ke hawale hokar sote hain. Nabi ﷺ ne sone ke waqt bhi humein ek khoobsurat saleeqa sikhaya: safai, wuzu, Allah ka zikr, Qur'an ki tilawat, dua, apni hifazat ka intezam aur Allah par bharosa.",
    sections:[
      { heading:"Sone Se Pehle", ic:"🛏️", items:[
        "Sone se pehle apne badan aur kapdon ki safai ka khayal rakhein.",
        "Wuzu karke soyein. Nabi ﷺ ne sone ke liye wuzu karne aur phir dahini taraf letne ki hidayat di.",
        "Apna bistar check aur saaf kar lein.",
        "Bistar par jaane se pehle use haath ya kapde ke kinare se jhaad lena Sunnah hai, kyunke humein nahi maloom ke hamari ghair-maujoodgi mein us par kya aa gaya ho.",
        "Kamre ko jitna mumkin ho saaf, comfortable aur sukoon wala rakhein.",
        "Sone se pehle zaroori cheezein apni jagah rakh dein, taaki raat ko be-wajah disturbance na ho.",
        "Ghar ke darwaze band karna aur Allah ka naam lena Sunnah mein aata hai.",
        "Paani ke bartan aur doosre khule containers ko dhak dena bhi Sunnah mein aata hai.",
        "Agar aag, diya ya koi unsafe flame ho toh use bujha kar soyein. Nabi ﷺ ne sone se pehle fire ko bujhane ki hidayat di."
      ] },
      { heading:"Sone Se Pehle Phone Se Bhi Ijazat Lijiye", ic:"📱", items:[
        "Sone se pehle be-wajah scrolling band karein.",
        "Bed ko endless social media browsing ki jagah sirf sukoon aur aaram ke liye istemal karne ki aadat banayein.",
        "Sone se pehle bahas, tez-mizaj chats aur be-zaroorat online guftugu se bachein.",
        "Kisi zaroori message ka jawab subah bhi diya ja sakta hai.",
        "Phone ko bistar se thoda door rakhna faida-mand ho sakta hai.",
        "Notifications ko silent ya sleep mode par rakh sakte hain.",
        "Sone ke bilkul waqt tak screen dekhte rehne ke bajaye apne zehan ko aaram dene ka waqt dein. (Yeh modern sleep hygiene ki baatein hain, inhe Sunnah ka seedha hukm na samjhein, maqsad sirf yeh hai ke technology hamari neend aur ibadat dono par ghalib na ho.)"
      ] },
      { heading:"Isha Ke Baad Raat Ko Be-Wajah Lamba Na Kheenchein", ic:"🕋", items:[
        "Nabi ﷺ Isha se pehle sone aur Isha ke baad be-zaroorat baat-cheet ko pasand nahi farmate the. Iska matlab yeh nahi ke Isha ke baad har guftugu mana hai, zaroori kaam, ilm, ghar ke maamlaat aur faida-mand baatein is se alag hain.",
        "Be-zaroorat raat ki gossip, endless scrolling, be-maqsad bahas aur bila wajah der tak jagna hamari neend, Fajr aur agle din ki salahiyat ko mutasir kar sakta hai. Raat ko khatam karna bhi ek saleeqa hai."
      ] },
      { heading:"Ayat-ul-Kursi", ic:"📖", items:[
        "Sone se pehle Ayat-ul-Kursi padhna masnoon hai. Sahih al-Bukhari mein Abu Hurairah RA ki riwayat mein iski hifazat ka zikr aata hai."
      ] },
      { heading:"Surah Al-Mulk", ic:"🌙", items:[
        "Sone se pehle Surah Al-Mulk padhna bhi ek khoobsurat raat ka amal banaya ja sakta hai.",
        "Surah Al-Mulk ke fazail ke hawale se riwayat milti hai ke 30 ayaat wali ek Surah apne padhne wale ke liye shafa'at karti rahi, yahan tak ke uski maghfirat kar di gayi, aur woh Surah Al-Mulk hai (Jami' at-Tirmidhi).",
        "Isliye ise sirf 'sone ki Surah' samajhne ke bajaye Qur'an ki tilawat aur Allah ki maghfirat ki umeed ke saath padhein. Raat ka waqt chhota ho sakta hai, lekin Qur'an ke saath guzara hua waqt qeemti hai."
      ] },
      { heading:"Surah Ikhlas, Falaq Aur Naas", ic:"🤍", items:[
        "Sone se pehle Surah Ikhlas, Surah Falaq aur Surah Naas padhein.",
        "Nabi ﷺ in teenon Surahon ko padhkar apne haathon par halki phoonk karte aur apne jism par pherte, aur teen martaba aisa karte the. Yeh raat ki hifazat aur Allah par tawakkul ka khoobsurat amal hai."
      ] },
      { heading:"Surah Baqarah Ki Aakhri Do Ayaat", ic:"📖", items:[
        "Raat mein Surah Baqarah ki aakhri do ayaat padhna bhi fazilat wala amal hai.",
        "Nabi ﷺ ne farmaya ke jo shakhs raat mein Surah Baqarah ki aakhri do ayaat padhe, woh uske liye kaafi hain."
      ] },
      { heading:"Tasbih-e-Fatima RA", ic:"🌿", items:[
        "Sone se pehle Tasbih-e-Fatima RA bhi padhein: SubhanAllah 33 martaba, Alhamdulillah 33 martaba, Allahu Akbar 34 martaba, kul 100 martaba.",
        "Ali RA se riwayat hai ke Fatima RA ne ghar ke kaam ki mushaqqat ki wajah se khadim ki darkhwast ki, toh Nabi ﷺ ne unhein sone ke waqt yeh zikr sikhaya aur farmaya ke yeh tumhare liye khadim se behtar hai.",
        "Sochiye: Nabi ﷺ ne apni beti ko sirf duniya ki aasani nahi, balki Allah ke zikr se milne wali roohani taqat ka raasta bataya. Is zikr ko raat ki routine ka hissa bana sakte hain."
      ] },
      { heading:"Sone Ki Dua", ic:"🤲", items:[
        "Sone ke waqt Nabi ﷺ yeh dua padhte: 'Bismika Allahumma amutu wa ahya'. Matlab: 'Ae Allah! Tere hi naam ke saath main marta hoon aur jeeta hoon.' Yeh dua Sahih al-Bukhari mein riwayat hai.",
        "Ek aur lambi masnoon dua bhi Nabi ﷺ ne sone se pehle padhne ki taleem di, jisme Allah ke saamne apne aap ko surrender karna aur apne tamam maamlaat Allah ke hawale karna shamil hai."
      ] },
      { heading:"Dahini Taraf Sona", ic:"🛌", items:[
        "Sone ke waqt dahini taraf letna Sunnah hai.",
        "Nabi ﷺ ne Al-Bara bin Azib RA ko sone ke liye wuzu karne, phir dahini taraf letne aur masnoon dua padhne ki hidayat di.",
        "Nabi ﷺ se sone ke waqt dahina haath gaal ke neeche rakhna bhi riwayat hua hai, aur pairon ko halka modna.",
        "Isliye sone ka ek khoobsurat Sunnah tareeqa ho sakta hai: wuzu, azkaar, dua, dahini taraf letna, aur Allah ke hawale hokar sona."
      ] },
      { heading:"Tahajjud Ki Niyyat Karke Sona", ic:"🌃", items:[
        "Raat ko sote waqt apne dil mein Tahajjud ke liye uthne ka irada rakhein. Alarm lagaiye, jaldi sone ki koshish kijiye aur Allah se dua kijiye: 'Ya Allah, mujhe raat mein apni ibadat ke liye utha dena.'",
        "Tahajjud ki niyyat karke sona ek khoobsurat intention hai, lekin sirf niyyat par rukna nahi, uthne ke liye practical sabab bhi ikhtiyar karein: alarm lagayein, phone ko bistar se thoda door rakhein, sone ka waqt be-wajah late na karein, aur agar mumkin ho toh kisi ghar wale ko bhi jagane ko keh sakte hain.",
        "Uthne par wuzu karein aur Tahajjud ada karein. Aur agar kisi raat aankh na khule, toh apne aap ko mayoos na karein, agli raat phir niyyat kijiye."
      ] },
      { heading:"Fajr Ke Liye Uthne Ka Irada", ic:"🕌", items:[
        "Raat ko sote waqt yeh niyyat bhi rakhein: 'Mujhe Fajr ke liye uthna hai.' Fajr ko miss karne ke baad subah ki routine banana maqsad nahi, Fajr ke liye raat se hi tayyari shuru hoti hai.",
        "Tarteeb kuch yun ho sakti hai: Tahajjud ki niyyat, Fajr ke liye alarm, wuzu, mumkin ho toh Tahajjud, phir Fajr ki namaz. Aur agar Tahajjud ke liye na uth sakein, toh Fajr ke liye zaroor uthna hai.",
        "Fajr farz hai, Tahajjud nafl ibadat hai, isliye raat ki planning mein dono ka darja alag samajhna zaroori hai."
      ] },
      { heading:"Sone Se Pehle Dil Ko Bhi Sulaayein", ic:"🧠", items:[
        "Kabhi jism bistar par hota hai, lekin zehan abhi bhi 'usne mujhe yeh kyun kaha', 'kal kya hoga', 'mera kaam complete nahi hua' jaisi baaton mein laga hota hai. Sone se pehle apne dil ko bhi release karna seekhein.",
        "Jo ho gaya, usko Allah ke hawale karein. Jo kal karna hai, uski planning kar lein. Jo aapke ikhtiyar mein nahi, us par tawakkul karein.",
        "Kisi ke liye baddua aur gusse ko lekar sone ki aadat se bachein, aur apne aap ko yaad dilayein: 'Jo mere bas mein tha, maine koshish ki, ab Allah ke hawale.'"
      ] },
      { heading:"Kisi Se Naraz Hain?", ic:"❤️", items:[
        "Har ikhtilaf ko raat bhar apne dil mein lekar chalna zaroori nahi. Agar kisi se galat-fehmi hui hai aur use suljhana mumkin ho, toh munasib waqt par baat kijiye.",
        "Lekin raat ko 'main kabhi maaf nahi karunga' ya 'kal usko sabak sikhaunga' jaise khayalat lekar sona aapke apne sukoon ko bhi khatam kar sakta hai.",
        "Maaf kar dena hamesha masle ko nazar-andaz karna nahi hota, kabhi iska matlab yeh hota hai ke aap apne dil ko be-zaroorat bojh se azaad kar rahe hain."
      ] },
      { heading:"Bhari Pet Se Sone Ki Aadat Se Bachein", ic:"🍽️", items:[
        "Sone se bilkul pehle bahut bhari khana neend aur hazme ko disturb kar sakta hai.",
        "Raat ko be-zaroorat zyada khana na khayein, aur sirf boriyat ki wajah se late-night snacking se bachein.",
        "Agar bhook lage toh zarurat ke mutabiq khayein, aur khane ke baad foran bistar par lete jaane ke bajaye apne jism ko settle hone ka waqt dein. (Yeh sehat aur neend se juda mashwara hai, koi khaas Sunnah hukm nahi.)"
      ] },
      { heading:"Safai Aur Zaati Hifazat", ic:"🧼", items:[
        "Sone se pehle jism saaf rakhein, aur zarurat ho toh wash karein.",
        "Munh aur daanton ki safai ka khayal rakhein, aur apne kapde aaramdeh aur saaf rakhein.",
        "Paseene ya badbu ke saath kisi shared sone ki jagah par na soyein, aur agar bistar kisi aur ke saath share karte hain toh unke aaram ka bhi khayal rakhein. Safai din ka hi nahi, raat ka bhi adab hai."
      ] },
      { heading:"Ghar Ki Hifazat Ka Khayal Rakhein", ic:"🔥", items:[
        "Sone se pehle ek jaldi check kar lein: gas stove band hai, diya ya candle bujh gayi hai, koi unsafe electrical cheez off hai, darwaza mehfooz hai, charging wires safe hain, bachche mehfooz jagah par hain, aur paani ke bartan dhake hue hain.",
        "Nabi ﷺ ne raat ko darwaze band karne, bartanon ko dhakne aur chiraghon/aag ko bujhane ki hidayat di. Yani ibadat ke saath practical hifazat bhi Deen ke adab ka hissa ban sakti hai."
      ] },
      { heading:"Neend Ko Sanjeedgi Se Lijiye", ic:"⏰", items:[
        "Neend ko 'waqt ki barbaadi' samajhna bhi sahi nahi, jism ko aaram chahiye. Agar aap roz raat gaye tak jaagte hain aur Fajr, kaam, taleem, warzish aur ghar ki zimmedariyan sab mutasir hone lagti hain, toh apni routine par dobara ghaur karein.",
        "Apni sone ki timing had tak consistent rakhein, raat ko be-zaroorat jagne ki aadat kam karein, aur subah ke zaroori kaam ko dekhte hue raat ki planning karein. Neend poori karna bhi apni jismani sehat ki zimmedari hai."
      ] },
      { heading:"Qailullah, Dopahar Ki Chhoti Neend", ic:"☀️", items:[
        "Qailullah dopahar ke waqt li jaane wali aaram ki neend ko kaha jata hai. Islam ki riwayat mein dopahar ke aaram ka zikr milta hai, aur yeh jism aur zehan ko dobara taazgi dene ka ek achha zariya ho sakta hai.",
        "Dopahar mein thodi der aaram karne se thakan kam ho sakti hai, zehni tawajjoh behtar ho sakti hai aur din ke baqi hisson ke liye taqat mil sakti hai.",
        "Sains mein bhi dopahar ki chhoti neend aur zehni sehat ke darmiyan achhe talluqat report hue hain. Ek paanch saal ki tadreeji tahqeeq mein 65 saal se zyada umar ke afraad mein 1 se 29 minute ki din ki neend zehni girawat ke kam khatre ke saath mutalliq payi gayi (PubMed tahqeeq).",
        "Isliye yeh kehna zyada durust hai ke takriban 30 minute ki chhoti dopahar ki neend zehni sehat ke liye faida-mand ho sakti hai, lekin tahqeeq abhi yeh sabit nahi karti ke '30 minute ki neend dementia ko door kar deti hai'. Tahqeeqat mein lambi ya zarurat se zyada neend ke saath dementia ya zehni kamzori ke mukhtalif talluqat bhi mile hain (PubMed tahqeeq).",
        "Qailullah ki koi ek muqarrarah muddat Qur'an ya Sahih Hadith mein tay nahi ki gayi. Amli taur par 30 se 60 minute ka aaram munasib ho sakta hai, lekin agar lambi neend se raat ki neend ya din ki routine mutasir ho, toh is ka waqt kam kar dena chahiye.",
        "Qailullah ka maqsad poora din sona nahi, balki thodi der aaram karke baqi din ko behtar tareeqe se guzarna hai."
      ] },
      { heading:"Sone Ka Matlab Kal Se Bhaagna Nahi", ic:"🌅", items:[
        "Sone se pehle apne aap se teen sawal pooch sakte hain: aaj maine Allah ko kitna yaad kiya? Aaj maine kisi insaan ko takleef toh nahi di? Kal mujhe kya behtar karna hai?",
        "Phir apne din ko Allah ke hawale karke so jaiye."
      ] },
      { heading:"Jaagte Hi", ic:"🌄", items:[
        "Nabi ﷺ jaagne par Allah ka shukr ada karne ki dua padhte: 'Alhamdu lillahil-lazi ahyana ba'da ma amatana wa ilaihin-nushur.' Matlab: 'Sab tareef Allah ke liye hai jisne humein maut jaisi neend ke baad zinda kiya, aur usi ki taraf laut kar jaana hai.' (Sahih al-Bukhari)",
        "Yani raat ka ikhtitaam bhi Allah ke zikr se, aur subah ki ibtida bhi Allah ke zikr se."
      ] },
      { heading:"Ek Khoobsurat Night Routine", ic:"🌌", items:[
        "Agar in sab ko ek simple tareeqe mein samete, toh raat kuch yun guzar sakti hai: apna kaam wrap-up karein, phone side par rakhein, safai/zaati hifazat ka khayal rakhein, wuzu karein, bistar check/jhaad lein, Ayat-ul-Kursi padhein, phir Ikhlas, Falaq aur Naas teen martaba, Surah Baqarah ki aakhri do ayaat aur Surah Al-Mulk, Tasbih-e-Fatima RA, masnoon sone ki dua, Tahajjud ki niyyat, Fajr ke liye alarm, aur phir dahini taraf let kar Allah ke hawale hokar so jaiye."
      ] },
    ],
    closing:"Neend bhi Allah ki nemat hai. Raat ko phone, tension aur be-ant scrolling ke hawale karne ke bajaye, apni raat ko sukoon, zikr, dua aur tawakkul ke saath khatam kijiye. Din duniya ke kaam mein guzra ho, toh raat Allah ke zikr se khatam kijiye. Ho sakta hai kal ki subah aapki zindagi ka ek aur behtar din ho." },
];
